@lru_cache(maxsize=512)
def rust_code_tokens(source: str) -> tuple[str, ...]:
    """Tokenize Rust/Verus structure after removing comments and literals."""

    return tuple(_RUST_TOKEN_RE.findall(mask_rust_comments_and_literals(source)))


def _rust_item_token_sha256(item: RustItem) -> str:
    """Hash one comment/literal-free item token stream unambiguously."""

    encoded = "\0".join(rust_code_tokens(item.source)).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _rust_sealed_item_token_sha256(item: RustItem) -> str:
    """Hash one item's declaration together with every leading attribute."""

    source = "\n".join((*item.attributes, item.source))
    encoded = "\0".join(rust_code_tokens(source)).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _rust_statement_token_sha256(statement: RustStatement) -> str:
    """Hash one exact top-level statement token stream unambiguously."""

    encoded = "\0".join(statement.tokens).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _rust_delimiter_context(
    structural_source: str, end: int
) -> tuple[tuple[str, int, tuple[str, ...]], ...]:
    """Return every unmatched delimiter ancestor enclosing ``end``."""

    stack: list[tuple[str, int, tuple[str, ...]]] = []
    matching = {')': '(', ']': '[', '}': '{'}
    last_boundary = 0
    for index, char in enumerate(structural_source[:end]):
        if char in "([{":
            stack.append(
                (
                    char,
                    index,
                    rust_code_tokens(structural_source[last_boundary:index]),
                )
            )
            if char == "{":
                last_boundary = index + 1
        elif char in ")]}":
            if stack and stack[-1][0] == matching[char]:
                stack.pop()
            else:
                stack.append((f"unmatched:{char}", index, ()))
            if char == "}":
                last_boundary = index + 1
        elif char == ";":
            last_boundary = index + 1
    return tuple(stack)


def _rust_brace_context(
    structural_source: str, end: int
) -> tuple[tuple[str, ...], ...]:
    """Return tokenized headers for curly-brace ancestors enclosing ``end``."""

    return tuple(
        header
        for opener, _position, header in _rust_delimiter_context(
            structural_source, end
        )
        if opener == "{"
    )


def _rust_attribute_end(structural_source: str, start: int) -> int:
    """Return the exclusive end of one bracketed Rust attribute."""

    opening = structural_source.find("[", start)
    if opening < 0:
        return start
    depth = 0
    for index in range(opening, len(structural_source)):
        if structural_source[index] == "[":
            depth += 1
        elif structural_source[index] == "]":
            depth -= 1
            if depth == 0:
                return index + 1
    return len(structural_source)


def _rust_ancestor_inner_cfg_attributes(
    source: str,
    structural_source: str,
    start: int,
    item_context: tuple[tuple[str, int, tuple[str, ...]], ...],
) -> tuple[str, ...]:
    """Collect file/ancestor inner cfg attributes that suppress an item."""

    item_positions = tuple(position for _opener, position, _header in item_context)
    attributes: list[str] = []
    pattern = re.compile(r"#\s*!\s*\[\s*cfg(?:_attr)?\b")
    for match in pattern.finditer(structural_source, 0, start):
        context = _rust_delimiter_context(structural_source, match.start())
        positions = tuple(position for _opener, position, _header in context)
        if positions != item_positions[: len(positions)]:
            continue
        end = _rust_attribute_end(structural_source, match.start())
        attributes.append(source[match.start() : end])
    return tuple(attributes)


def _leading_rust_attributes(
    source: str, structural_source: str, start: int
) -> tuple[str, ...]:
    """Collect contiguous attributes immediately preceding an item."""

    attributes: list[str] = []
    cursor = start
    while True:
        while cursor > 0 and structural_source[cursor - 1].isspace():
            cursor -= 1
        if cursor == 0 or structural_source[cursor - 1] != "]":
            break
        depth = 1
        opening = cursor - 2
        while opening >= 0 and depth:
            if structural_source[opening] == "]":
                depth += 1
            elif structural_source[opening] == "[":
                depth -= 1
            opening -= 1
        if depth:
            break
        opening += 1
        hash_index = opening - 1
        if hash_index >= 0 and structural_source[hash_index] == "!":
            hash_index -= 1
        if hash_index < 0 or structural_source[hash_index] != "#":
            break
        attributes.append(source[hash_index:cursor])
        cursor = hash_index
    attributes.reverse()
    return tuple(attributes)


def _token_sequence_count(
    haystack: Sequence[str], needle: Sequence[str]
) -> int:
    """Count contiguous token sequences without accepting comment stuffing."""

    width = len(needle)
    if width == 0:
        return 0
    return sum(
        tuple(haystack[index : index + width]) == tuple(needle)
        for index in range(len(haystack) - width + 1)
    )


def rust_items(source: str, name: str) -> tuple[RustItem, ...]:
    """Extract all real Rust/Verus function items named ``name``."""

    structural = mask_rust_comments_and_literals(source)
    declaration = re.compile(
        rf"(?m)^[ \t]*(?:pub(?:\s*\([^\n)]*\))?[ \t]+)?"
        rf"(?:(?:async|const)[ \t]+)*"
        rf"(?:(?:open|closed|broadcast|tracked|exec|spec|proof)[ \t]+)*"
        rf"fn[ \t]+{re.escape(name)}\b"
    )
    items: list[RustItem] = []
    for match in declaration.finditer(structural):
        paren_depth = 0
        bracket_depth = 0
        body_start = -1
        for index in range(match.end(), len(structural)):
            char = structural[index]
            if char == "(":
                paren_depth += 1
            elif char == ")":
                paren_depth = max(0, paren_depth - 1)
            elif char == "[":
                bracket_depth += 1
            elif char == "]":
                bracket_depth = max(0, bracket_depth - 1)
            elif char == "{" and paren_depth == 0 and bracket_depth == 0:
                body_start = index
                break
            elif char == ";" and paren_depth == 0 and bracket_depth == 0:
                break
        if body_start < 0:
            continue
        depth = 0
        body_end = -1
        for index in range(body_start, len(structural)):
            if structural[index] == "{":
                depth += 1
            elif structural[index] == "}":
                depth -= 1
                if depth == 0:
                    body_end = index + 1
                    break
        if body_end < 0:
            continue
        start = match.start()
        item_source = source[start:body_end]
        delimiter_context = _rust_delimiter_context(structural, start)
        items.append(
            RustItem(
                name=name,
                line=source.count("\n", 0, start) + 1,
                source=item_source,
                body=source[body_start + 1 : body_end - 1],
                structural_source=structural[start:body_end],
                brace_context=_rust_brace_context(structural, start),
                delimiter_context=delimiter_context,
                attributes=_leading_rust_attributes(source, structural, start),
                ancestor_inner_attributes=_rust_ancestor_inner_cfg_attributes(
                    source,
                    structural,
                    start,
                    delimiter_context,
                ),
            )
        )
    return tuple(items)


def rust_struct_items(source: str, name: str) -> tuple[RustItem, ...]:
    """Extract all real brace-delimited Rust/Verus structs named ``name``."""

    structural = mask_rust_comments_and_literals(source)
    declaration = re.compile(
        rf"(?m)^[ \t]*(?:pub(?:\s*\([^\n)]*\))?[ \t]+)?"
        rf"struct[ \t]+{re.escape(name)}\b"
    )
    items: list[RustItem] = []
    for match in declaration.finditer(structural):
        body_start = structural.find("{", match.end())
        if body_start < 0:
            continue
        semicolon = structural.find(";", match.end(), body_start)
        if semicolon >= 0:
            continue
        depth = 0
        body_end = -1
        for index in range(body_start, len(structural)):
            if structural[index] == "{":
                depth += 1
            elif structural[index] == "}":
                depth -= 1
                if depth == 0:
                    body_end = index + 1
                    break
        if body_end < 0:
            continue
        start = match.start()
        delimiter_context = _rust_delimiter_context(structural, start)
        items.append(
            RustItem(
                name=name,
                line=source.count("\n", 0, start) + 1,
                source=source[start:body_end],
                body=source[body_start + 1 : body_end - 1],
                structural_source=structural[start:body_end],
                brace_context=_rust_brace_context(structural, start),
                delimiter_context=delimiter_context,
                attributes=_leading_rust_attributes(source, structural, start),
                ancestor_inner_attributes=_rust_ancestor_inner_cfg_attributes(
                    source,
                    structural,
                    start,
                    delimiter_context,
                ),
            )
        )
    return tuple(items)


def rust_macro_items(source: str, name: str) -> tuple[RustItem, ...]:
    """Extract all real brace-delimited ``macro_rules!`` items named ``name``."""

    structural = mask_rust_comments_and_literals(source)
    declaration = re.compile(
        rf"(?m)^[ \t]*macro_rules\s*!\s*{re.escape(name)}\b"
    )
    items: list[RustItem] = []
    for match in declaration.finditer(structural):
        body_start = structural.find("{", match.end())
        if body_start < 0:
            continue
        # A semicolon before the opening delimiter cannot begin a real macro
        # item; fail closed instead of scanning into a later declaration.
        semicolon = structural.find(";", match.end(), body_start)
        if semicolon >= 0:
            continue
        depth = 0
        body_end = -1
        for index in range(body_start, len(structural)):
            if structural[index] == "{":
                depth += 1
            elif structural[index] == "}":
                depth -= 1
                if depth == 0:
                    body_end = index + 1
                    break
        if body_end < 0:
            continue
        start = match.start()
        delimiter_context = _rust_delimiter_context(structural, start)
        items.append(
            RustItem(
                name=name,
                line=source.count("\n", 0, start) + 1,
                source=source[start:body_end],
                body=source[body_start + 1 : body_end - 1],
                structural_source=structural[start:body_end],
                brace_context=_rust_brace_context(structural, start),
                delimiter_context=delimiter_context,
                attributes=_leading_rust_attributes(source, structural, start),
                ancestor_inner_attributes=_rust_ancestor_inner_cfg_attributes(
                    source,
                    structural,
                    start,
                    delimiter_context,
                ),
            )
        )
    return tuple(items)


def rust_top_level_statements(source: str) -> tuple[RustStatement, ...]:
    """Extract real semicolon-terminated statements at file brace depth zero."""

    structural = mask_rust_comments_and_literals(source)
    statements: list[RustStatement] = []
    stack: list[str] = []
    matching = {')': '(', ']': '[', '}': '{'}
    start = 0
    for index, char in enumerate(structural):
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if stack and stack[-1] == matching[char]:
                stack.pop()
            else:
                stack.append(f"unmatched:{char}")
            if char == "}" and not stack:
                lookahead = index + 1
                while lookahead < len(structural) and structural[lookahead].isspace():
                    lookahead += 1
                if lookahead >= len(structural) or structural[lookahead] != ";":
                    start = index + 1
        elif char == ";" and not stack:
            statement_source = source[start : index + 1]
            tokens = rust_code_tokens(statement_source)
            if tokens:
                statements.append(
                    RustStatement(
                        line=source.count("\n", 0, start) + 1,
                        source=statement_source,
                        tokens=tokens,
                        ancestor_inner_attributes=(
                            _rust_ancestor_inner_cfg_attributes(
                                source,
                                structural,
                                start,
                                (),
                            )
                        ),
                    )
                )
            start = index + 1
    return tuple(statements)


def _require_rust_item(
    path: Path,
    source: str,
    name: str,
    errors: list[str],
) -> RustItem | None:
    """Return one named item, recording a fail-closed cardinality error."""

    items = rust_items(source, name)
    if len(items) != 1:
        errors.append(
            f"{path}: require exactly one real Rust/Verus function item "
            f"named {name}; found {len(items)}"
        )
        return None
    return items[0]


def _require_qualified_rust_item(
    path: Path,
    source: str,
    impl_name: str,
    item_name: str,
    errors: list[str],
    description: str,
    *,
    expected_attributes: tuple[str, ...] = (),
) -> RustItem | None:
    """Return one method from the exact reviewed impl, rejecting lookalikes."""

    expected_context = (("impl", impl_name),)
    matching = [
        item
        for item in rust_items(source, item_name)
        if item.brace_context == expected_context
    ]
    if len(matching) != 1:
        errors.append(
            f"{path}: require exactly one real Rust/Verus function item named "
            f"{impl_name}::{item_name}; found {len(matching)}"
        )
        return None
    item = matching[0]
    _require_rust_item_context(
        path,
        item,
        expected_context,
        description,
        errors,
        expected_attributes=expected_attributes,
    )
    return item


def _require_rust_item_context(
    path: Path,
    item: RustItem | None,
    expected_context: tuple[tuple[str, ...], ...],
    description: str,
    errors: list[str],
    *,
    expected_attributes: tuple[str, ...] = (),
) -> None:
    """Reject macro nesting and disabled replacements for a reviewed item."""

    if item is None:
        return
    if item.brace_context != expected_context:
        errors.append(
            f"{path}:{item.line}: {description} must have reviewed brace context "
            f"{expected_context!r}; found {item.brace_context!r}"
        )
    delimiter_context = tuple(
        (opener, header)
        for opener, _position, header in item.delimiter_context
    )
    expected_delimiters = tuple(("{", header) for header in expected_context)
    if delimiter_context != expected_delimiters:
        errors.append(
            f"{path}:{item.line}: {description} must have reviewed all-delimiter "
            f"context {expected_delimiters!r}; found {delimiter_context!r}"
        )
    if item.ancestor_inner_attributes:
        errors.append(
            f"{path}:{item.line}: {description} may not be suppressed by "
            "file/module/ancestor inner cfg/cfg_attr attributes: "
            f"{item.ancestor_inner_attributes!r}"
        )
    gated = [
        attribute
        for attribute in item.attributes
        if re.search(r"(?s)^#\s*\[\s*cfg(?:_attr)?\b", attribute)
    ]
    if gated:
        errors.append(
            f"{path}:{item.line}: {description} may not be disabled or replaced "
            f"through cfg/cfg_attr attributes: {gated!r}"
        )
    elif item.attributes != expected_attributes:
        errors.append(
            f"{path}:{item.line}: {description} must have exact reviewed "
            f"attributes {expected_attributes!r}; found {item.attributes!r}"
        )


def _require_exact_rust_tokens(
    path: Path,
    item: RustItem | None,
    expected_source: str,
    description: str,
    errors: list[str],
) -> None:
    """Require one extracted item to equal an exact code-token contract."""

    if item is not None and rust_code_tokens(item.source) != rust_code_tokens(
        expected_source
    ):
        errors.append(
            f"{path}:{item.line}: {description} must match the exact reviewed "
            "Rust/Verus item body"
        )


def _require_rust_token_sequence(
    path: Path,
    item: RustItem | None,
    expected_source: str,
    description: str,
    errors: list[str],
    *,
    count: int = 1,
) -> None:
    """Require an exact token subsequence in one extracted real item."""

    if item is None:
        return
    observed = _token_sequence_count(
        rust_code_tokens(item.source), rust_code_tokens(expected_source)
    )
    if observed != count:
        errors.append(
            f"{path}:{item.line}: {description} must occur exactly {count} "
            f"time(s) in the real {item.name} item; found {observed}"
        )


def _require_rust_item_token_sha256(
    path: Path,
    item: RustItem | None,
    expected_sha256: str,
    description: str,
    errors: list[str],
) -> None:
    """Require the complete extracted item to retain its reviewed token seal."""

    if item is None:
        return
    observed_sha256 = _rust_item_token_sha256(item)
    if observed_sha256 != expected_sha256:
        errors.append(
            f"{path}:{item.line}: {description} declaration and complete control "
            "flow must match the exact reviewed token digest "
            f"{expected_sha256}; found {observed_sha256}"
        )


def _require_rust_source_token_sequence(
    path: Path,
    source: str,
    expected_source: str,
    description: str,
    errors: list[str],
    *,
    count: int = 1,
) -> None:
    """Require one exact token sequence in a regular Rust source file."""

    observed = _token_sequence_count(
        rust_code_tokens(source), rust_code_tokens(expected_source)
    )
    if observed != count:
        errors.append(
            f"{path}: {description} must occur exactly {count} time(s) in "
            f"executable Rust source; found {observed}"
        )


def tla_shortcut_errors(path: Path, source: str) -> list[str]:
    """Find unchecked top-level assumptions, axioms, and omitted proofs."""

    stripped = strip_tla_comments(source)
    structured_assumptions: set[int] = set()
    for declaration in ANY_THEOREM_DECLARATION_RE.finditer(stripped):
        body_start = declaration.end()
        next_declaration = re.compile(
            r"(?m)^(?:[A-Za-z_][A-Za-z0-9_]*\s*"
            r"(?:\([^)=\n]*\))?\s*==|[ \t]*(?:LOCAL[ \t]+)?"
            r"(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)\b|={4,}\s*$)"
        ).search(stripped, body_start)
        body_end = (
            next_declaration.start()
            if next_declaration is not None
            else len(stripped)
        )
        body = stripped[body_start:body_end]
        proof = THEOREM_PROOF_MARKER_RE.search(body)
        if proof is None:
            continue
        statement = body[: proof.start()]
        assumption = re.match(
            r"(?is)\s*(?P<token>ASSUME)\b",
            statement,
        )
        if assumption is None:
            continue
        if STRUCTURED_PROVE_RE.search(statement, assumption.end()) is None:
            continue
        structured_assumptions.add(body_start + assumption.start("token"))

    errors: list[str] = []
    for match in TOP_LEVEL_TRUST_RE.finditer(stripped):
        if match.start("token") in structured_assumptions:
            continue
        line = stripped.count("\n", 0, match.start()) + 1
        token = match.group("token")
        errors.append(f"{path}:{line}: unchecked top-level {token} is prohibited")
    for match in OMITTED_RE.finditer(stripped):
        line = stripped.count("\n", 0, match.start()) + 1
        errors.append(f"{path}:{line}: OMITTED proof is prohibited")
    return errors


def verus_shortcut_errors(path: Path, source: str) -> list[str]:
    """Find Verus assumption/admission and unreviewed trusted-body escapes."""

    structural = mask_rust_comments_and_literals(source)
    errors: list[str] = []
    for match in VERUS_ESCAPE_RE.finditer(structural):
        line = structural.count("\n", 0, match.start()) + 1
        token = " ".join(match.group(0).split())
        errors.append(f"{path}:{line}: Verus proof escape is prohibited: {token}")
    return errors


def _nonempty_string(value: Any) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _symbol_names(symbol_field: str) -> tuple[str, ...]:
    return tuple(part.strip() for part in symbol_field.split("/") if part.strip())


def _symbol_exists(module_source: str, symbol: str, *, theorem_only: bool = False) -> bool:
    """Return whether ``symbol`` has the required top-level declaration shape."""

    stripped = strip_tla_comments(module_source)
    theorem_pattern = re.compile(
        THEOREM_DECLARATION_TEMPLATE.format(symbol=re.escape(symbol))
    )
    if theorem_only:
        return theorem_pattern.search(stripped) is not None
    operator_pattern = re.compile(DECLARATION_TEMPLATE.format(symbol=re.escape(symbol)))
    return (
        operator_pattern.search(stripped) is not None
        or theorem_pattern.search(stripped) is not None
    )


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _relative_to_root(path: Path, root_dir: Path = ROOT_DIR) -> str:
    try:
        return path.resolve().relative_to(root_dir.resolve()).as_posix()
    except ValueError as error:
        raise ValueError(f"path is outside the repository: {path}") from error


def _formal_source_manifest(
    formal_dir: Path = FORMAL_DIR, root_dir: Path = ROOT_DIR
) -> dict[str, Any]:
    """Hash every TLA+ model/proof source in one deterministic manifest."""

    files: list[dict[str, str]] = []
    aggregate = hashlib.sha256()
    for path in sorted(formal_dir.glob("*.tla")):
        relative = _relative_to_root(path, root_dir)
        digest = _sha256_file(path)
        files.append({"path": relative, "sha256": digest})
        aggregate.update(relative.encode("utf-8"))
        aggregate.update(b"\0")
        aggregate.update(digest.encode("ascii"))
        aggregate.update(b"\n")
    return {"sha256": aggregate.hexdigest(), "files": files}


def _tlapm_runner_marker(module: str, source_manifest_sha256: str) -> str:
    """Return the exact marker appended only after a strict TLAPM run succeeds."""

    return (
        f"{TLAPM_RUNNER_MARKER_PREFIX} module={module} commit={TLAPM_COMMIT} "
        f"source_manifest_sha256={source_manifest_sha256}"
    )


def _tlapm_obligation_count(
    log_source: str, *, module: str, source_manifest_sha256: str
) -> int | None:
    """Validate a pinned TLAPM log and return its exact proved count.

    TLAPM 1.6.0-pre emits one final ``[INFO]: All N obligation(s) proved.``
    line on success.  The repository runner appends one manifest-bound marker
    after that line.  Requiring this exact two-line suffix prevents a stale,
    partial, or marker-stuffed log from becoming release evidence.
    """

    if not log_source.endswith("\n"):
        return None
    lines = log_source.splitlines()
    expected_marker = _tlapm_runner_marker(module, source_manifest_sha256)
    if len(lines) < 2 or lines[-1] != expected_marker:
        return None
    if sum(line.startswith(TLAPM_RUNNER_MARKER_PREFIX) for line in lines) != 1:
        return None
    completion_lines = [
        match
        for line in lines
        if (match := TLAPM_COMPLETE_RE.fullmatch(line)) is not None
    ]
    if len(completion_lines) != 1:
        return None
    completion = TLAPM_COMPLETE_RE.fullmatch(lines[-2])
    if completion is None:
        return None
    return int(completion.group(1))


def _canonical_json_sha256(value: Any) -> str:
    """Hash a JSON value using the evidence contract's canonical encoding."""

    encoded = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


@lru_cache(maxsize=1)
def _verus_evidence_contract_module() -> Any:
    """Load the independently pinned Verus evidence validator."""

    path = ROOT_DIR / "scripts" / "formal" / "sumeragi_v2_verus_evidence.py"
    spec = importlib.util.spec_from_file_location(
        "_sumeragi_v2_verus_evidence_contract", path
    )
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load Verus evidence contract: {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _cross_tool_contract_errors() -> list[str]:
    """Check the immutable 4 + 7 + 6 refinement mapping itself."""

    errors: list[str] = []
    expected_ids = (
        "effective-lock-body-acquisition-production-refinement",
        "progress-witness-production-refinement",
        "successor-activation-exact-recovery-production-refinement",
    )
    observed_ids = tuple(
        contract.obligation_id for contract in CROSS_TOOL_REFINEMENT_CONTRACTS
    )
    if observed_ids != expected_ids:
        errors.append(
            "cross-tool obligation inventory must equal the canonical three "
            f"production seams {expected_ids!r}; found {observed_ids!r}"
        )
    observed_counts = tuple(
        len(contract.claims) for contract in CROSS_TOOL_REFINEMENT_CONTRACTS
    )
    if observed_counts != (4, 7, 6):
        errors.append(
            "cross-tool production claim cardinalities must equal (4, 7, 6); "
            f"found {observed_counts!r}"
        )

    expected_premises = {
        "effective-lock-body-acquisition-production-refinement": (
            "ProductionEffectiveLockBodyAcquisitionRefinement"
        ),
        "progress-witness-production-refinement": (
            "ProductionProgressWitnessTraceRefinement"
        ),
        "successor-activation-exact-recovery-production-refinement": (
            "ProductionSuccessorAndExactRecoveryTraceRefinement"
        ),
    }
    expected_ledger_bindings = {
        "effective-lock-body-acquisition-production-refinement": (
            "operator",
            "/\\ ProductionEffectiveLockBodyAcquisitionRefinement "
            "/\\ EffectiveLockAcquisitionModelObligation",
            "BY EffectiveLockAcquisitionModelObligation "
            "DEF EffectiveLockBodyAcquisitionProductionRefinementObligation",
        ),
        "progress-witness-production-refinement": (
            "operator",
            "/\\ ProductionProgressWitnessTraceRefinement "
            "/\\ ProgressWitnessObligation",
            "BY ProgressWitnessObligation "
            "DEF ProgressWitnessProductionRefinementObligation",
        ),
        "successor-activation-exact-recovery-production-refinement": (
            "operator",
            "/\\ ProductionSuccessorAndExactRecoveryTraceRefinement "
            "/\\ (IndexedChainSpec => []"
            "SuccessorActivationAndExactHistoricalRecoveryProductionRefinementInvariant)",
            "BY IndexedChainSpecEstablishesSuccessorActivationAndExactHistoricalRecoveryInvariant "
            "DEF SuccessorActivationAndExactHistoricalRecoveryProductionRefinementObligation",
        ),
    }

    constants: list[str] = []
    verus_theorems: list[str] = []
    tla_theorems: list[str] = []
    for contract in CROSS_TOOL_REFINEMENT_CONTRACTS:
        reviewed_target = REQUIRED_PROOF_OBLIGATION_INVENTORY.get(
            contract.obligation_id
        )
        if reviewed_target != (contract.module, contract.ledger_symbol):
            errors.append(
                f"cross-tool contract {contract.obligation_id} targets "
                f"{(contract.module, contract.ledger_symbol)!r}, not reviewed "
                f"ledger target {reviewed_target!r}"
            )
        expected_premise = expected_premises.get(contract.obligation_id)
        expected_statement = (
            None
            if expected_premise is None
            else f"{expected_premise} => {contract.ledger_symbol}"
        )
        if contract.tla_statement != expected_statement:
            errors.append(
                f"cross-tool contract {contract.obligation_id} must imply its "
                f"exact ledger theorem symbol using {expected_statement!r}; "
                f"found {contract.tla_statement!r}"
            )
        expected_ledger_binding = expected_ledger_bindings.get(
            contract.obligation_id, (None, None, None)
        )
        observed_ledger_binding = (
            contract.ledger_declaration_kind,
            contract.ledger_statement,
            contract.tla_proof,
        )
        if observed_ledger_binding != expected_ledger_binding:
            errors.append(
                f"cross-tool contract {contract.obligation_id} must bind the exact "
                "reviewed ledger declaration kind, normalized definition, and bridge "
                f"proof {expected_ledger_binding!r}; found {observed_ledger_binding!r}"
            )
        tla_theorems.append(contract.tla_theorem)
        for claim in contract.claims:
            constants.append(claim.constant)
            verus_theorems.append(claim.verus_theorem)
            if not claim.production_sources:
                errors.append(
                    f"cross-tool claim {claim.constant} has no production sources"
                )
            for relative in (claim.verus_source, *claim.production_sources):
                path = Path(relative)
                if path.is_absolute() or ".." in path.parts:
                    errors.append(
                        f"cross-tool claim {claim.constant} has unsafe source path "
                        f"{relative!r}"
                    )
    for label, values, expected_count in (
        ("TLA constants", constants, 17),
        ("Verus theorem names", verus_theorems, 17),
        ("TLA theorem names", tla_theorems, 3),
    ):
        if len(values) != expected_count or len(set(values)) != expected_count:
            errors.append(
                f"cross-tool {label} must contain {expected_count} unique names"
            )
    return errors


def _rust_parameter_names(parameters: str) -> tuple[str, ...]:
    """Return simple named Rust parameters from one reviewed signature fragment."""

    # Cross-tool kernels deliberately use a flat, named projection signature.
    # Rejecting patterns/destructuring here keeps the source-fidelity check
    # unambiguous and prevents a changed projection from hiding in syntax the
    # checker does not normalize.
    names = re.findall(
        r"(?:^|,)\s*(?:mut\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*:", parameters
    )
    return tuple(names)


def _normalized_rust_contract(source: str) -> str:
    """Normalize one code-owned Rust/Verus contract to its token stream."""

    return " ".join(rust_code_tokens(source))


def _rust_precondition_is_obviously_contradictory(
    tokens: Sequence[str],
) -> bool:
    """Recognize literal and simple conjunctive Rust/Verus contradictions.

    This deliberately stays syntactic.  It catches proof placeholders such as
    `requires false`, `x, !x`, `x != x`, conflicting literal equalities, and
    exact inverse comparisons without pretending to be an SMT solver.  Clauses
    containing implication are kept opaque so a contradictory antecedent is
    not mistaken for a contradictory precondition.
    """

    matching = {")": "(", "]": "[", "}": "{"}

    def strip_outer(value: tuple[str, ...]) -> tuple[str, ...]:
        while len(value) >= 2 and value[0] == "(" and value[-1] == ")":
            depth = 0
            closes_at_end = False
            for index, token in enumerate(value):
                if token == "(":
                    depth += 1
                elif token == ")":
                    depth -= 1
                    if depth == 0:
                        closes_at_end = index == len(value) - 1
                        break
            if not closes_at_end:
                break
            value = value[1:-1]
        return value

    def split_top_level(
        value: tuple[str, ...], separator: str
    ) -> list[tuple[str, ...]]:
        parts: list[tuple[str, ...]] = []
        start = 0
        stack: list[str] = []
        for index, token in enumerate(value):
            if token in "([{":
                stack.append(token)
            elif token in matching:
                if stack and stack[-1] == matching[token]:
                    stack.pop()
            elif token == separator and not stack:
                parts.append(strip_outer(value[start:index]))
                start = index + 1
        parts.append(strip_outer(value[start:]))
        return [part for part in parts if part]

    def contains_implication(value: tuple[str, ...]) -> bool:
        return any(
            value[index : index + 2] == ("==", ">")
            for index in range(len(value) - 1)
        )

    def is_atom(value: tuple[str, ...]) -> bool:
        return bool(value) and all(
            re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", token)
            or token in (".", "::")
            for token in value
        )

    clauses = split_top_level(tuple(tokens), ",")
    atoms: list[tuple[str, ...]] = []
    for clause in clauses:
        if clause == ("false",):
            return True
        if contains_implication(clause):
            continue
        atoms.extend(split_top_level(clause, "&&"))

    positive: set[tuple[str, ...]] = set()
    negative: set[tuple[str, ...]] = set()
    equal_literals: dict[tuple[str, ...], str] = {}
    comparisons: set[tuple[tuple[str, ...], str, tuple[str, ...]]] = set()
    inverse = {"<": ">=", ">=": "<", ">": "<=", "<=": ">", "==": "!=", "!=": "=="}
    for raw_atom in atoms:
        atom = strip_outer(raw_atom)
        if atom == ("false",):
            return True
        if len(atom) > 1 and atom[0] == "!" and is_atom(atom[1:]):
            negative.add(atom[1:])
            continue
        if is_atom(atom):
            positive.add(atom)
            continue

        stack: list[str] = []
        operator_index: int | None = None
        operator = ""
        for index, token in enumerate(atom):
            if token in "([{":
                stack.append(token)
                continue
            if token in matching:
                if stack and stack[-1] == matching[token]:
                    stack.pop()
                continue
            if not stack and token in ("==", "!=", "<", "<=", ">", ">="):
                if token == "==" and index + 1 < len(atom) and atom[index + 1] == ">":
                    break
                operator_index = index
                operator = token
                break
        if operator_index is None:
            continue
        left = strip_outer(atom[:operator_index])
        right = strip_outer(atom[operator_index + 1 :])
        if not left or not right:
            continue
        if left == right and operator in ("!=", "<", ">"):
            return True
        comparison = (left, operator, right)
        if (left, inverse[operator], right) in comparisons:
            return True
        comparisons.add(comparison)
        if operator == "==" and is_atom(left) and len(right) == 1 and re.fullmatch(
            r"(?:true|false|[0-9]+(?:u(?:8|16|32|64|128|size))?)", right[0]
        ):
            prior = equal_literals.setdefault(left, right[0])
            if prior != right[0]:
                return True

    return bool(positive & negative)


def _rust_top_level_clauses(
    tokens: Sequence[str], separator: str = ","
) -> tuple[tuple[str, ...], ...]:
    """Split one Rust/Verus clause list without crossing nested delimiters."""

    matching = {")": "(", "]": "[", "}": "{"}

    def strip_outer(value: tuple[str, ...]) -> tuple[str, ...]:
        while len(value) >= 2 and value[0] == "(" and value[-1] == ")":
            depth = 0
            closes_at_end = False
            for index, token in enumerate(value):
                if token == "(":
                    depth += 1
                elif token == ")":
                    depth -= 1
                    if depth == 0:
                        closes_at_end = index == len(value) - 1
                        break
            if not closes_at_end:
                break
            value = value[1:-1]
        return value

    value = tuple(tokens)
    parts: list[tuple[str, ...]] = []
    start = 0
    stack: list[str] = []
    for index, token in enumerate(value):
        if token in "([{":
            stack.append(token)
        elif token in matching:
            if stack and stack[-1] == matching[token]:
                stack.pop()
        elif token == separator and not stack:
            clause = strip_outer(value[start:index])
            if clause:
                parts.append(clause)
            start = index + 1
    clause = strip_outer(value[start:])
    if clause:
        parts.append(clause)
    return tuple(parts)


def _rust_clause_is_obviously_tautological(tokens: Sequence[str]) -> bool:
    """Recognize constant or reflexive Rust/Verus postcondition atoms."""

    clause = tuple(tokens)
    if clause == ("true",):
        return True
    stack: list[str] = []
    matching = {")": "(", "]": "[", "}": "{"}
    for index, token in enumerate(clause):
        if token in "([{":
            stack.append(token)
            continue
        if token in matching:
            if stack and stack[-1] == matching[token]:
                stack.pop()
            continue
        if stack:
            continue
        if token in ("==", "<=", ">="):
            if token == "==" and index + 1 < len(clause) and clause[index + 1] == ">":
                left = clause[:index]
                right = clause[index + 2 :]
            else:
                left = clause[:index]
                right = clause[index + 1 :]
            return bool(left) and left == right
    return False


def _cross_tool_promotion_contract_errors(
    contracts: Sequence[CrossToolObligationContract],
) -> list[str]:
    """Reject incomplete or vacuous contracts before proof promotion."""

    errors: list[str] = []
    kernel_names: list[str] = []
    call_site_keys: list[tuple[str, str]] = []
    for obligation in contracts:
        for claim in obligation.claims:
            fields = {
                "verus_parameters": claim.verus_parameters,
                "verus_requires": claim.verus_requires,
                "verus_ensures": claim.verus_ensures,
                "verified_kernel": claim.verified_kernel,
                "verified_kernel_source": claim.verified_kernel_source,
                "verified_kernel_parameters": claim.verified_kernel_parameters,
                "verified_kernel_body": claim.verified_kernel_body,
                "theorem_kernel_projection": claim.theorem_kernel_projection,
                "theorem_projection_builder": claim.theorem_projection_builder,
                "theorem_projection_builder_parameters": (
                    claim.theorem_projection_builder_parameters
                ),
                "theorem_projection_builder_return": (
                    claim.theorem_projection_builder_return
                ),
                "theorem_projection_builder_item_sha256": (
                    claim.theorem_projection_builder_item_sha256
                ),
            }
            missing = [
                name for name, value in fields.items() if not _nonempty_string(value)
            ]
            if missing:
                errors.append(
                    f"cross-tool claim {claim.constant} lacks exact promotion "
                    f"contract fields {missing!r}"
                )
                continue

            # The preceding completeness check narrows each optional field.
            parameters = claim.verus_parameters
            requires = claim.verus_requires
            ensures = claim.verus_ensures
            kernel = claim.verified_kernel
            kernel_source = claim.verified_kernel_source
            kernel_parameters = claim.verified_kernel_parameters
            kernel_body = claim.verified_kernel_body
            projection = claim.theorem_kernel_projection
            projection_builder = claim.theorem_projection_builder
            projection_builder_parameters = (
                claim.theorem_projection_builder_parameters
            )
            projection_builder_return = claim.theorem_projection_builder_return
            projection_builder_item_sha256 = (
                claim.theorem_projection_builder_item_sha256
            )
            assert isinstance(parameters, str)
            assert isinstance(requires, str)
            assert isinstance(ensures, str)
            assert isinstance(kernel, str)
            assert isinstance(kernel_source, str)
            assert isinstance(kernel_parameters, str)
            assert isinstance(kernel_body, str)
            assert isinstance(projection, str)
            assert isinstance(projection_builder, str)
            assert isinstance(projection_builder_parameters, str)
            assert isinstance(projection_builder_return, str)
            assert isinstance(projection_builder_item_sha256, str)

            if re.fullmatch(
                r"[A-Za-z_][A-Za-z0-9_]*", projection_builder
            ) is None:
                errors.append(
                    f"cross-tool claim {claim.constant} has invalid Verus projection "
                    f"builder name {projection_builder!r}"
                )
            if re.fullmatch(
                r"[0-9a-f]{64}", projection_builder_item_sha256
            ) is None:
                errors.append(
                    f"cross-tool claim {claim.constant} has invalid Verus projection "
                    "builder token digest"
                )

            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", kernel) is None:
                errors.append(
                    f"cross-tool claim {claim.constant} has invalid verified kernel "
                    f"name {kernel!r}"
                )
            else:
                kernel_names.append(kernel)
            path = Path(kernel_source)
            if path.is_absolute() or ".." in path.parts:
                errors.append(
                    f"cross-tool claim {claim.constant} has unsafe verified kernel "
                    f"source {kernel_source!r}"
                )

            theorem_parameter_names = _rust_parameter_names(parameters)
            kernel_parameter_names = _rust_parameter_names(kernel_parameters)
            if not theorem_parameter_names:
                errors.append(
                    f"cross-tool claim {claim.constant} must have an exact named "
                    "Verus projection parameter"
                )
            if not kernel_parameter_names:
                errors.append(
                    f"cross-tool claim {claim.constant} must have an exact named "
                    "kernel projection parameter"
                )

            requires_tokens = rust_code_tokens(requires)
            ensures_tokens = rust_code_tokens(ensures)
            projection_tokens = rust_code_tokens(projection)
            kernel_body_tokens = rust_code_tokens(kernel_body)
            kernel_call_tokens = rust_code_tokens(f"{kernel}({projection})")
            normalized_kernel_projection = _normalized_rust_contract(
                f"{kernel}({projection})"
            )
            requires_clauses = set(_rust_top_level_clauses(requires_tokens))
            ensures_clauses = _rust_top_level_clauses(ensures_tokens)
            if requires_tokens in ((), ("true",)):
                errors.append(
                    f"cross-tool claim {claim.constant} has a vacuous Verus "
                    "requires clause"
                )
            elif _rust_precondition_is_obviously_contradictory(requires_tokens):
                errors.append(
                    f"cross-tool claim {claim.constant} has an obviously "
                    "contradictory Verus requires clause"
                )
            if ensures_tokens in ((), ("true",), ("false",)):
                errors.append(
                    f"cross-tool claim {claim.constant} has a vacuous or constant "
                    "Verus ensures clause"
                )
            elif ensures_tokens == requires_tokens:
                errors.append(
                    f"cross-tool claim {claim.constant} Verus ensures must not restate "
                    "its exact requires clause"
                )
            elif _rust_precondition_is_obviously_contradictory(ensures_tokens):
                errors.append(
                    f"cross-tool claim {claim.constant} has an obviously "
                    "contradictory Verus ensures clause"
                )
            kernel_clause_count = sum(
                clause == kernel_call_tokens for clause in ensures_clauses
            )
            kernel_call_count = _token_sequence_count(
                ensures_tokens, kernel_call_tokens
            )
            if kernel_clause_count != 1 or kernel_call_count != 1:
                errors.append(
                    f"cross-tool claim {claim.constant} ensures must contain the "
                    "exact verified kernel projection once as a top-level clause: "
                    f"{normalized_kernel_projection!r}"
                )
            postconditions = tuple(
                clause for clause in ensures_clauses if clause != kernel_call_tokens
            )
            nontrivial_postconditions = tuple(
                clause
                for clause in postconditions
                if clause not in requires_clauses
                and not _rust_clause_is_obviously_tautological(clause)
            )
            if not nontrivial_postconditions:
                errors.append(
                    f"cross-tool claim {claim.constant} must retain at least one "
                    "reviewed nontrivial postcondition beyond its kernel and "
                    "requires clauses"
                )
            disconnected_precondition_inputs = [
                name for name in theorem_parameter_names if name not in requires_tokens
            ]
            disconnected_projection_inputs = [
                name for name in theorem_parameter_names if name not in projection_tokens
            ]
            projection_builder_call_count = _token_sequence_count(
                projection_tokens, (projection_builder, "(")
            )
            if disconnected_precondition_inputs:
                errors.append(
                    f"cross-tool claim {claim.constant} requires does not depend on "
                    f"every Verus parameter: {disconnected_precondition_inputs!r}"
                )
            if disconnected_projection_inputs:
                errors.append(
                    f"cross-tool claim {claim.constant} kernel projection does not "
                    f"carry every Verus parameter: {disconnected_projection_inputs!r}"
                )
            if projection_builder_call_count != 1:
                errors.append(
                    f"cross-tool claim {claim.constant} kernel projection must call "
                    f"its exact Verus builder {projection_builder} once"
                )
            missing_kernel_inputs = [
                name for name in kernel_parameter_names if name not in kernel_body_tokens
            ]
            obvious_kernel_tautology = any(
                kernel_body_tokens == (name, operator, name)
                for name in kernel_parameter_names
                for operator in ("==", "<=", ">=")
            )
            if (
                kernel_body_tokens in ((), ("true",), ("false",))
                or missing_kernel_inputs
                or obvious_kernel_tautology
            ):
                errors.append(
                    f"cross-tool claim {claim.constant} verified kernel contract "
                    "must be nonconstant and depend on every projection input"
                )

            if not claim.production_call_sites:
                errors.append(
                    f"cross-tool claim {claim.constant} has no authoritative production "
                    "kernel call sites"
                )
            for call_site in claim.production_call_sites:
                call_site_keys.append((call_site.source, call_site.item))
                if (
                    re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", call_site.item)
                    is None
                    or not _nonempty_string(call_site.projection)
                    or not _nonempty_string(call_site.required_expression)
                ):
                    errors.append(
                        f"cross-tool claim {claim.constant} has an incomplete or "
                        "invalid authoritative production call-site contract"
                    )
                if any(
                    "test" in header or "bench" in header
                    for header in call_site.brace_context
                ):
                    errors.append(
                        f"cross-tool claim {claim.constant} call site "
                        f"{call_site.source}!{call_site.item} may not be test-only"
                    )
                if call_site.source not in claim.production_sources:
                    errors.append(
                        f"cross-tool claim {claim.constant} call site "
                        f"{call_site.source}!{call_site.item} is outside its reviewed "
                        "production source inventory"
                    )
                path = Path(call_site.source)
                if path.is_absolute() or ".." in path.parts:
                    errors.append(
                        f"cross-tool claim {claim.constant} has unsafe call-site source "
                        f"{call_site.source!r}"
                    )
                call_tokens = rust_code_tokens(
                    f"{kernel}({call_site.projection})"
                )
                expression_tokens = rust_code_tokens(call_site.required_expression)
                if _token_sequence_count(expression_tokens, call_tokens) != 1:
                    errors.append(
                        f"cross-tool claim {claim.constant} required production "
                        f"expression must invoke {kernel} with its exact projection once"
                    )
                if not (
                    {"assert", "assert_eq", "ensure", "if", "match", "return"}
                    & set(expression_tokens)
                ):
                    errors.append(
                        f"cross-tool claim {claim.constant} production expression "
                        "must enforce the verified boolean kernel result"
                    )

    if len(kernel_names) != len(set(kernel_names)):
        errors.append("cross-tool verified kernel names must be globally unique")
    if len(call_site_keys) != len(set(call_site_keys)):
        errors.append(
            "cross-tool authoritative production source/item pairs must be globally unique"
        )
    return errors


def _cross_tool_status_contracts(
    ledger: dict[str, Any],
) -> tuple[CrossToolObligationContract, ...]:
    obligations = ledger.get("obligations")
    if not isinstance(obligations, list):
        return ()
    statuses = {
        obligation.get("id"): obligation.get("status")
        for obligation in obligations
        if isinstance(obligation, dict)
    }
    return tuple(
        contract
        for contract in CROSS_TOOL_REFINEMENT_CONTRACTS
        if statuses.get(contract.obligation_id) == "cross_tool_proved"
    )


def _cross_tool_dependency_entries(
    ledger: dict[str, Any], contract: CrossToolObligationContract
) -> list[dict[str, str]]:
    """Return the exact transitive proved-prerequisite closure."""

    obligations = ledger.get("obligations")
    if not isinstance(obligations, list):
        raise ValueError("proof ledger obligations must be an array")
    by_id = {
        obligation.get("id"): obligation
        for obligation in obligations
        if isinstance(obligation, dict) and _nonempty_string(obligation.get("id"))
    }
    entries: list[dict[str, str]] = []
    for prerequisite_id in _proof_dependency_closure(contract.obligation_id):
        prerequisite = by_id.get(prerequisite_id)
        if prerequisite is None:
            raise ValueError(
                f"cross-tool obligation {contract.obligation_id} is missing "
                f"prerequisite {prerequisite_id}"
            )
        status = prerequisite.get("status")
        if status not in PROVED_STATUS_VALUES:
            raise ValueError(
                f"cross-tool obligation {contract.obligation_id} requires proved "
                f"prerequisite {prerequisite_id}, found {status!r}"
            )
        entries.append({"id": prerequisite_id, "status": status})
    return entries


def _proof_dependency_closure(obligation_id: str) -> tuple[str, ...]:
    """Return prerequisites in deterministic dependency-before-dependent order."""

    ordered: list[str] = []
    visited: set[str] = set()
    visiting: set[str] = set()

    def visit(current: str) -> None:
        if current in visiting:
            raise ValueError(
                f"proof dependency graph contains a cycle through {current}"
            )
        if current in visited:
            return
        visiting.add(current)
        for prerequisite in PROOF_STATUS_DEPENDENCIES.get(current, ()):
            visit(prerequisite)
            if prerequisite not in visited:
                visited.add(prerequisite)
                ordered.append(prerequisite)
        visiting.remove(current)

    visit(obligation_id)
    return tuple(ordered)


def _tla_statement_without_proof(body: str) -> str:
    """Normalize the statement prefix of one TLA+ theorem/operator body."""

    statement = THEOREM_PROOF_MARKER_RE.split(body, maxsplit=1)[0]
    return " ".join(statement.split())


def _strip_balanced_outer_parentheses(expression: str) -> str:
    """Remove balanced parentheses which wrap one complete TLA+ expression."""

    result = expression.strip()
    while result.startswith("(") and result.endswith(")"):
        depth = 0
        closes_at_end = False
        for index, character in enumerate(result):
            if character == "(":
                depth += 1
            elif character == ")":
                depth -= 1
                if depth == 0:
                    closes_at_end = index == len(result) - 1
                    break
        if not closes_at_end:
            break
        result = result[1:-1].strip()
    return " ".join(result.split())


def _expanded_tla_alias(source: str, expression: str) -> str:
    """Expand a chain of parameterless top-level TLA+ aliases."""

    current = _strip_balanced_outer_parentheses(expression)
    visited: set[str] = set()
    while re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", current):
        if current in visited:
            raise ValueError(f"cyclic TLA+ alias in cross-tool seam: {current}")
        visited.add(current)
        declaration = _top_level_theorem_body(
            source, current, preserve_string_contents=True
        )
        if declaration is None:
            declaration = _top_level_operator_body(
                source, current, preserve_string_contents=True
            )
        if declaration is None:
            break
        body, _ = declaration
        expanded = _strip_balanced_outer_parentheses(
            _tla_statement_without_proof(body)
        )
        if not expanded:
            break
        current = expanded
    return current


def _cross_tool_tla_payload(
    contract: CrossToolObligationContract,
    *,
    tlaps_evidence: dict[str, Any],
    formal_dir: Path,
    root_dir: Path,
) -> dict[str, Any]:
    """Build one source- and strict-log-bound TLA theorem payload."""

    expected_tool = {
        "name": "TLAPM",
        "commit": TLAPM_COMMIT,
        "version": TLAPM_COMMIT[:7],
    }
    if tlaps_evidence.get("tool") != expected_tool:
        raise ValueError("cross-tool evidence requires the pinned TLAPM identity")
    expected_manifest = _formal_source_manifest(formal_dir, root_dir)
    if tlaps_evidence.get("source_manifest") != expected_manifest:
        raise ValueError(
            "cross-tool TLAPS evidence is stale relative to the current formal sources"
        )
    if tlaps_evidence.get("backend_verification") is not True:
        raise ValueError("cross-tool TLAPS evidence is not backend verified")

    module_path = formal_dir / f"{contract.module}.tla"
    if not module_path.is_file() or module_path.is_symlink():
        raise ValueError(
            f"cross-tool TLA source is not a regular file: {module_path}"
        )
    module_source = module_path.read_text(encoding="utf-8")
    premise = contract.tla_statement.split(" => ", maxsplit=1)[0]
    premise_operator = _top_level_operator_body(module_source, premise)
    if premise_operator is None:
        raise ValueError(
            f"cross-tool obligation {contract.obligation_id} is missing "
            f"production premise {contract.module}!{premise}"
        )
    premise_body, _ = premise_operator
    observed_premise = " ".join(premise_body.split())
    expected_premise = " ".join(
        f"/\\ {claim.constant} = TRUE" for claim in contract.claims
    )
    if observed_premise != expected_premise:
        raise ValueError(
            f"cross-tool production premise {contract.module}!{premise} must "
            "contain the exact ordered claim mapping "
            f"{expected_premise!r}; found {observed_premise!r}"
        )

    ledger_kind = contract.ledger_declaration_kind
    ledger_contract_statement = contract.ledger_statement
    if (ledger_kind is None) != (ledger_contract_statement is None):
        raise ValueError(
            f"cross-tool obligation {contract.obligation_id} has an incomplete "
            "ledger declaration contract"
        )
    observed_ledger_statement: str | None = None
    if ledger_kind is not None:
        if ledger_kind not in {"operator", "theorem"}:
            raise ValueError(
                f"cross-tool obligation {contract.obligation_id} has unsupported "
                f"ledger declaration kind {ledger_kind!r}"
            )
        ledger_operator = _top_level_operator_body(
            module_source,
            contract.ledger_symbol,
            preserve_string_contents=True,
        )
        ledger_theorem = _top_level_theorem_body(
            module_source,
            contract.ledger_symbol,
            preserve_string_contents=True,
        )
        if ledger_kind == "operator":
            ledger_declaration = ledger_operator
            swapped_declaration = ledger_theorem
        else:
            ledger_declaration = ledger_theorem
            swapped_declaration = ledger_operator
        if ledger_declaration is None or swapped_declaration is not None:
            raise ValueError(
                f"cross-tool ledger symbol {contract.module}!{contract.ledger_symbol} "
                f"must be declared exactly once as a top-level {ledger_kind}, not "
                "as a theorem/operator substitution"
            )
        ledger_body, _ = ledger_declaration
        observed_ledger_statement = _tla_statement_without_proof(ledger_body)
        expected_ledger_statement = " ".join(ledger_contract_statement.split())
        if observed_ledger_statement != expected_ledger_statement:
            raise ValueError(
                f"cross-tool ledger {ledger_kind} "
                f"{contract.module}!{contract.ledger_symbol} must state exactly "
                f"{expected_ledger_statement!r}; found {observed_ledger_statement!r}"
            )
    theorem = _top_level_theorem_body(
        module_source, contract.tla_theorem, preserve_string_contents=True
    )
    if theorem is None:
        raise ValueError(
            f"cross-tool obligation {contract.obligation_id} is missing named "
            f"TLA theorem {contract.module}!{contract.tla_theorem}"
        )
    theorem_body, _ = theorem
    theorem_parts = re.split(
        r"(?m)^[ \t]*(?:BY|PROOF|OBVIOUS)\b", theorem_body, maxsplit=1
    )
    statement = " ".join(theorem_parts[0].split())
    if statement != contract.tla_statement:
        raise ValueError(
            f"cross-tool theorem {contract.module}!{contract.tla_theorem} must "
            f"state exactly {contract.tla_statement!r}; found {statement!r}"
        )
    if len(theorem_parts) != 2:
        raise ValueError(
            f"cross-tool theorem {contract.module}!{contract.tla_theorem} "
            "must have an explicit proof body"
        )
    observed_proof = " ".join(theorem_parts[1].split())
    if contract.tla_proof is not None:
        expected_proof = " ".join(contract.tla_proof.split())
        if observed_proof != expected_proof:
            raise ValueError(
                f"cross-tool theorem {contract.module}!{contract.tla_theorem} "
                "must retain the exact model-obligation bridge proof "
                f"{expected_proof!r}; found {observed_proof!r}"
            )

    antecedent, consequent = contract.tla_statement.split(" => ", maxsplit=1)
    expanded_antecedent = _expanded_tla_alias(module_source, antecedent)
    expanded_consequent = _expanded_tla_alias(module_source, consequent)
    if expanded_consequent == "TRUE" or expanded_antecedent == expanded_consequent:
        raise ValueError(
            f"cross-tool theorem {contract.module}!{contract.tla_theorem} is "
            "definitionally tautological after expanding its production premise "
            "and ledger consequent"
        )

    modules = tlaps_evidence.get("modules")
    if not isinstance(modules, list):
        raise ValueError("cross-tool TLAPS evidence modules must be an array")
    matching = [
        entry
        for entry in modules
        if isinstance(entry, dict) and entry.get("module") == contract.module
    ]
    if len(matching) != 1:
        raise ValueError(
            f"cross-tool TLAPS evidence must contain exactly one {contract.module} log"
        )
    entry = matching[0]
    expected_log = f"target/formal/sumeragi_v2/tlaps/{contract.module}.log"
    if entry.get("log") != expected_log:
        raise ValueError(
            f"cross-tool TLAPS evidence must use strict log {expected_log}"
        )
    manifest_sha256 = expected_manifest["sha256"]
    if entry.get("source_manifest_sha256") != manifest_sha256:
        raise ValueError(
            f"cross-tool TLAPS log for {contract.module} is stale"
        )
    log_path = root_dir / expected_log
    if not log_path.is_file() or log_path.is_symlink():
        raise ValueError(f"cross-tool TLAPS log is not a regular file: {log_path}")
    log_sha256 = _sha256_file(log_path)
    if entry.get("log_sha256") != log_sha256:
        raise ValueError(
            f"cross-tool TLAPS log digest mismatch for {contract.module}"
        )
    proved = _tlapm_obligation_count(
        log_path.read_text(encoding="utf-8"),
        module=contract.module,
        source_manifest_sha256=manifest_sha256,
    )
    if proved is None or proved <= 0 or entry.get("obligations_proved") != proved:
        raise ValueError(
            f"cross-tool TLAPS log for {contract.module} lacks a fresh strict "
            "successful result"
        )
    return {
        "module": contract.module,
        "theorem": contract.tla_theorem,
        "statement": contract.tla_statement,
        "ledger_definition": (
            None
            if ledger_kind is None
            else {
                "symbol": contract.ledger_symbol,
                "kind": ledger_kind,
                "statement": observed_ledger_statement,
            }
        ),
        "normalized_proof_sha256": hashlib.sha256(
            observed_proof.encode("utf-8")
        ).hexdigest(),
        "normalized_antecedent_sha256": hashlib.sha256(
            expanded_antecedent.encode("utf-8")
        ).hexdigest(),
        "normalized_consequent_sha256": hashlib.sha256(
            expanded_consequent.encode("utf-8")
        ).hexdigest(),
        "source_sha256": _sha256_file(module_path),
        "log": expected_log,
        "log_sha256": log_sha256,
        "obligations_proved": proved,
    }


def _rust_item_header_tokens(item: RustItem) -> tuple[str, ...]:
    """Return the normalized declaration tokens preceding an item's body."""

    parentheses = 0
    brackets = 0
    for index, character in enumerate(item.structural_source):
        if character == "(":
            parentheses += 1
        elif character == ")":
            parentheses = max(0, parentheses - 1)
        elif character == "[":
            brackets += 1
        elif character == "]":
            brackets = max(0, brackets - 1)
        elif character == "{" and parentheses == 0 and brackets == 0:
            return rust_code_tokens(item.structural_source[:index])
    return ()


def _cross_tool_claim_contract_document(
    claim: CrossToolClaimContract,
) -> dict[str, Any]:
    """Return the code-owned exact claim contract in canonical JSON form."""

    return {
        "constant": claim.constant,
        "verus_theorem": claim.verus_theorem,
        "verus_source": claim.verus_source,
        "verus_parameters": _normalized_rust_contract(
            claim.verus_parameters or ""
        ),
        "verus_requires": _normalized_rust_contract(claim.verus_requires or ""),
        "verus_ensures": _normalized_rust_contract(claim.verus_ensures or ""),
        "verified_kernel": claim.verified_kernel,
        "verified_kernel_source": claim.verified_kernel_source,
        "verified_kernel_parameters": _normalized_rust_contract(
            claim.verified_kernel_parameters or ""
        ),
        "verified_kernel_body": _normalized_rust_contract(
            claim.verified_kernel_body or ""
        ),
        "verified_kernel_const": claim.verified_kernel_const,
        "verified_kernel_public": claim.verified_kernel_public,
        "verified_kernel_shared_macro_sha256": [
            {"name": name, "item_token_sha256": sha256}
            for name, sha256 in claim.verified_kernel_shared_macro_sha256
        ],
        "theorem_kernel_projection": _normalized_rust_contract(
            claim.theorem_kernel_projection or ""
        ),
        "theorem_projection_builder": claim.theorem_projection_builder,
        "theorem_projection_builder_parameters": _normalized_rust_contract(
            claim.theorem_projection_builder_parameters or ""
        ),
        "theorem_projection_builder_return": _normalized_rust_contract(
            claim.theorem_projection_builder_return or ""
        ),
        "theorem_projection_builder_item_sha256": (
            claim.theorem_projection_builder_item_sha256
        ),
        "source_item_seals": [
            {
                "source": seal.source,
                "item": seal.item,
                "kind": seal.kind,
                "brace_context": [list(header) for header in seal.brace_context],
                "item_token_sha256": seal.item_token_sha256,
            }
            for seal in claim.source_item_seals
        ],
        "production_call_sites": [
            {
                "source": call_site.source,
                "item": call_site.item,
                "brace_context": [list(header) for header in call_site.brace_context],
                "projection": _normalized_rust_contract(call_site.projection),
                "required_expression": _normalized_rust_contract(
                    call_site.required_expression
                ),
            }
            for call_site in claim.production_call_sites
        ],
    }


def _verus_source_entry(
    source_entries: list[Any], relative: str, *, description: str
) -> dict[str, Any]:
    """Return one exact source entry from linked Verus evidence."""

    matching = [
        entry
        for entry in source_entries
        if isinstance(entry, dict) and entry.get("path") == relative
    ]
    if len(matching) != 1:
        raise ValueError(
            f"cross-tool Verus evidence must bind {description} {relative}"
        )
    return matching[0]


def _shared_macro_payload(
    source: str,
    *,
    path: Path,
    expected: Iterable[tuple[str, str]],
    description: str,
) -> list[dict[str, str]]:
    """Validate and describe the exact macros shared by production and Verus."""

    payload: list[dict[str, str]] = []
    for name, expected_sha256 in expected:
        items = rust_macro_items(source, name)
        if len(items) != 1:
            raise ValueError(
                f"cross-tool {description} requires exactly one "
                f"shared macro {path}!{name}; found {len(items)}"
            )
        item = items[0]
        if item.brace_context != () or item.delimiter_context != ():
            raise ValueError(
                f"cross-tool shared macro {path}!{name} must be a top-level "
                "production item"
            )
        if item.attributes or item.ancestor_inner_attributes:
            raise ValueError(
                f"cross-tool shared macro {path}!{name} may not be gated or "
                "rewritten by attributes"
            )
        observed_sha256 = _rust_item_token_sha256(item)
        if observed_sha256 != expected_sha256:
            raise ValueError(
                f"cross-tool shared macro {path}!{name} does not match its exact "
                f"reviewed token seal {expected_sha256}; found {observed_sha256}"
            )
        payload.append(
            {
                "name": name,
                "item_token_sha256": observed_sha256,
            }
        )
    return payload


def _effective_lock_trace_shared_macro_payload(
    source: str, *, path: Path
) -> list[dict[str, str]]:
    """Validate the complete effective-lock shared-macro closure."""

    return _shared_macro_payload(
        source,
        path=path,
        expected=_EFFECTIVE_LOCK_TRACE_SHARED_MACRO_SHA256.items(),
        description="effective-lock refinement",
    )


def _cross_tool_source_item_seal_payload(
    claim: CrossToolClaimContract, *, root_dir: Path
) -> list[dict[str, Any]]:
    """Validate code-owned type/extractor seals in one claim's identity closure."""

    allowed_sources = {
        claim.verus_source,
        claim.verified_kernel_source,
        *claim.production_sources,
    }
    payload: list[dict[str, Any]] = []
    for seal in claim.source_item_seals:
        if seal.source not in allowed_sources:
            raise ValueError(
                f"cross-tool source seal {seal.source}!{seal.item} is outside "
                f"claim {claim.constant}'s declared source closure"
            )
        path = root_dir / seal.source
        if not path.is_file() or path.is_symlink():
            raise ValueError(f"cross-tool source seal is not a regular file: {path}")
        source = path.read_text(encoding="utf-8")
        if seal.kind == "const":
            if seal.brace_context:
                raise ValueError(
                    f"cross-tool top-level const seal {seal.source}!{seal.item} "
                    "cannot declare a brace context"
                )
            statements = tuple(
                statement
                for statement in rust_top_level_statements(source)
                if _token_sequence_count(
                    statement.tokens,
                    ("const", seal.item),
                )
                == 1
            )
            if len(statements) != 1:
                raise ValueError(
                    "cross-tool source seal requires exactly one top-level const "
                    f"{seal.source}!{seal.item}; found {len(statements)}"
                )
            statement = statements[0]
            if statement.ancestor_inner_attributes:
                raise ValueError(
                    f"cross-tool source seal {seal.source}!{seal.item} may not be "
                    "enclosed by a cfg or lint-changing attribute"
                )
            observed_sha256 = _rust_statement_token_sha256(statement)
            if observed_sha256 != seal.item_token_sha256:
                raise ValueError(
                    f"cross-tool source seal {seal.source}!{seal.item} does not match "
                    f"reviewed token seal {seal.item_token_sha256}; found "
                    f"{observed_sha256}"
                )
            payload.append(
                {
                    "source": seal.source,
                    "item": seal.item,
                    "kind": seal.kind,
                    "brace_context": [],
                    "item_token_sha256": observed_sha256,
                }
            )
            continue
        if seal.kind == "item":
            items = rust_items(source, seal.item)
        elif seal.kind == "struct":
            items = rust_struct_items(source, seal.item)
        elif seal.kind == "macro":
            items = rust_macro_items(source, seal.item)
        else:
            raise ValueError(
                f"cross-tool source seal {seal.source}!{seal.item} has unknown "
                f"kind {seal.kind!r}"
            )
        if len(items) != 1:
            raise ValueError(
                f"cross-tool source seal requires exactly one {seal.kind} "
                f"{seal.source}!{seal.item}; found {len(items)}"
            )
        item = items[0]
        if item.brace_context != seal.brace_context:
            raise ValueError(
                f"cross-tool source seal {seal.source}!{seal.item} moved from its "
                "reviewed declaration context"
            )
        if item.ancestor_inner_attributes:
            raise ValueError(
                f"cross-tool source seal {seal.source}!{seal.item} may not be "
                "enclosed by a cfg or lint-changing attribute"
            )
        observed_sha256 = _rust_sealed_item_token_sha256(item)
        if observed_sha256 != seal.item_token_sha256:
            raise ValueError(
                f"cross-tool source seal {seal.source}!{seal.item} does not match "
                f"reviewed token seal {seal.item_token_sha256}; found "
                f"{observed_sha256}"
            )
        payload.append(
            {
                "source": seal.source,
                "item": seal.item,
                "kind": seal.kind,
                "brace_context": [list(header) for header in seal.brace_context],
                "item_token_sha256": observed_sha256,
            }
        )
    return payload


def _enter_view_identity_production_item_payload(
    source: str, *, path: Path
) -> list[dict[str, str]]:
    """Validate the complete concrete QC extraction/classification call path."""

    payload: list[dict[str, str]] = []
    for name, expected_sha256 in _ENTER_VIEW_IDENTITY_PRODUCTION_ITEM_SHA256.items():
        items = rust_items(source, name)
        if len(items) != 1:
            raise ValueError(
                "cross-tool EnterView identity refinement requires exactly one "
                f"production item {path}!{name}; found {len(items)}"
            )
        item = items[0]
        if item.brace_context != (("impl", "Reducer"),):
            raise ValueError(
                f"cross-tool EnterView identity item {path}!{name} must remain "
                "inside the authoritative Reducer implementation"
            )
        if item.attributes or item.ancestor_inner_attributes:
            raise ValueError(
                f"cross-tool EnterView identity item {path}!{name} may not be "
                "gated or rewritten by attributes"
            )
        observed_sha256 = _rust_item_token_sha256(item)
        if observed_sha256 != expected_sha256:
            raise ValueError(
                f"cross-tool EnterView identity item {path}!{name} does not match "
                f"its exact reviewed token seal {expected_sha256}; found "
                f"{observed_sha256}"
            )
        payload.append({"name": name, "item_token_sha256": observed_sha256})
    substitution_items = rust_items(source, _ENTER_VIEW_IDENTITY_SUBSTITUTION_TEST)
    if len(substitution_items) != 1:
        raise ValueError(
            "cross-tool EnterView identity refinement requires exactly one "
            "full-certificate substitution regression; found "
            f"{len(substitution_items)}"
        )
    substitution = substitution_items[0]
    if substitution.brace_context != (
        ("#", "[", "cfg", "(", "test", ")", "]", "mod", "source_link_tests"),
    ):
        raise ValueError(
            "cross-tool EnterView full-certificate substitution regression must "
            "remain in source_link_tests"
        )
    if tuple(rust_code_tokens(attribute) for attribute in substitution.attributes) != (
        ("#", "[", "test", "]"),
    ) or substitution.ancestor_inner_attributes:
        raise ValueError(
            "cross-tool EnterView full-certificate substitution regression must "
            "remain an unconditional #[test]"
        )
    substitution_sha256 = _rust_item_token_sha256(substitution)
    if substitution_sha256 != _ENTER_VIEW_IDENTITY_SUBSTITUTION_TEST_SHA256:
        raise ValueError(
            "cross-tool EnterView full-certificate substitution regression does "
            "not match its exact reviewed token seal "
            f"{_ENTER_VIEW_IDENTITY_SUBSTITUTION_TEST_SHA256}; found "
            f"{substitution_sha256}"
        )
    payload.append(
        {
            "name": _ENTER_VIEW_IDENTITY_SUBSTITUTION_TEST,
            "item_token_sha256": substitution_sha256,
        }
    )
    return payload


def _cross_tool_claim_payload(
    claim: CrossToolClaimContract,
    *,
    verus_evidence: dict[str, Any],
    root_dir: Path,
) -> dict[str, Any]:
    """Build one named Verus theorem and exact production-source binding."""

    source_entries = verus_evidence.get("sources")
    if not isinstance(source_entries, list):
        raise ValueError("cross-tool Verus source inventory must be an array")
    proof_source_entry = _verus_source_entry(
        source_entries, claim.verus_source, description="proof source"
    )
    verus_path = root_dir / claim.verus_source
    if not verus_path.is_file() or verus_path.is_symlink():
        raise ValueError(
            f"cross-tool Verus proof source is not a regular file: {verus_path}"
        )
    verus_sha256 = _sha256_file(verus_path)
    if proof_source_entry.get("sha256") != verus_sha256:
        raise ValueError(
            f"cross-tool Verus proof source digest mismatch: {claim.verus_source}"
        )
    verus_source = verus_path.read_text(encoding="utf-8")
    theorem_items = rust_items(verus_source, claim.verus_theorem)
    if len(theorem_items) != 1:
        raise ValueError(
            f"cross-tool claim {claim.constant} requires exactly one named Verus "
            f"theorem {claim.verus_theorem}; found {len(theorem_items)}"
        )
    theorem_item = theorem_items[0]
    if theorem_item.brace_context != (("verus", "!"),):
        raise ValueError(
            f"cross-tool Verus result {claim.verus_theorem} must be a top-level "
            "item in the verified verus! module"
        )
    if theorem_item.attributes or theorem_item.ancestor_inner_attributes:
        raise ValueError(
            f"cross-tool Verus result {claim.verus_theorem} may not be gated or "
            "rewritten by attributes"
        )
    parameters = claim.verus_parameters
    requires = claim.verus_requires
    ensures = claim.verus_ensures
    kernel = claim.verified_kernel
    kernel_source = claim.verified_kernel_source
    kernel_parameters = claim.verified_kernel_parameters
    kernel_body = claim.verified_kernel_body
    theorem_projection = claim.theorem_kernel_projection
    projection_builder = claim.theorem_projection_builder
    projection_builder_parameters = claim.theorem_projection_builder_parameters
    projection_builder_return = claim.theorem_projection_builder_return
    projection_builder_item_sha256 = claim.theorem_projection_builder_item_sha256
    if not all(
        isinstance(value, str) and value.strip()
        for value in (
            parameters,
            requires,
            ensures,
            kernel,
            kernel_source,
            kernel_parameters,
            kernel_body,
            theorem_projection,
            projection_builder,
            projection_builder_parameters,
            projection_builder_return,
            projection_builder_item_sha256,
        )
    ):
        raise ValueError(
            f"cross-tool claim {claim.constant} has no complete exact promotion contract"
        )
    assert isinstance(parameters, str)
    assert isinstance(requires, str)
    assert isinstance(ensures, str)
    assert isinstance(kernel, str)
    assert isinstance(kernel_source, str)
    assert isinstance(kernel_parameters, str)
    assert isinstance(kernel_body, str)
    assert isinstance(theorem_projection, str)
    assert isinstance(projection_builder, str)
    assert isinstance(projection_builder_parameters, str)
    assert isinstance(projection_builder_return, str)
    assert isinstance(projection_builder_item_sha256, str)

    expected_theorem_header = rust_code_tokens(
        f"pub proof fn {claim.verus_theorem}({parameters}) "
        f"requires {requires}, ensures {ensures},"
    )
    observed_theorem_header = _rust_item_header_tokens(theorem_item)
    if observed_theorem_header != expected_theorem_header:
        raise ValueError(
            f"cross-tool Verus result {claim.verus_theorem} must have exact "
            "normalized signature, parameters, requires, and ensures; expected "
            f"{(' '.join(expected_theorem_header))!r}, found "
            f"{(' '.join(observed_theorem_header))!r}"
        )
    expected_proof_call = rust_code_tokens(
        f"{kernel}({theorem_projection})"
    )
    proof_call_count = _token_sequence_count(
        rust_code_tokens(theorem_item.body), expected_proof_call
    )
    if proof_call_count != 1:
        raise ValueError(
            f"cross-tool Verus result {claim.verus_theorem} must invoke its "
            f"verified kernel with the exact projection once; found {proof_call_count}"
        )

    projection_builder_items = rust_items(verus_source, projection_builder)
    if len(projection_builder_items) != 1:
        raise ValueError(
            f"cross-tool claim {claim.constant} requires exactly one Verus live "
            f"projection builder {claim.verus_source}!{projection_builder}; found "
            f"{len(projection_builder_items)}"
        )
    projection_builder_item = projection_builder_items[0]
    if projection_builder_item.brace_context != (("verus", "!"),):
        raise ValueError(
            f"cross-tool Verus projection builder {projection_builder} must be a "
            "top-level item in the verified verus! module"
        )
    if (
        projection_builder_item.attributes
        or projection_builder_item.ancestor_inner_attributes
    ):
        raise ValueError(
            f"cross-tool Verus projection builder {projection_builder} may not be "
            "gated or rewritten by attributes"
        )
    expected_projection_builder_header = rust_code_tokens(
        f"pub closed spec fn {projection_builder}("
        f"{projection_builder_parameters}) -> {projection_builder_return}"
    )
    observed_projection_builder_header = _rust_item_header_tokens(
        projection_builder_item
    )
    if observed_projection_builder_header != expected_projection_builder_header:
        raise ValueError(
            f"cross-tool Verus projection builder {projection_builder} must have "
            f"exact normalized signature "
            f"{(' '.join(expected_projection_builder_header))!r}; found "
            f"{(' '.join(observed_projection_builder_header))!r}"
        )
    observed_projection_builder_sha256 = _rust_item_token_sha256(
        projection_builder_item
    )
    if observed_projection_builder_sha256 != projection_builder_item_sha256:
        raise ValueError(
            f"cross-tool Verus projection builder {projection_builder} does not "
            f"match its exact reviewed token seal {projection_builder_item_sha256}; "
            f"found {observed_projection_builder_sha256}"
        )

    kernel_source_entry = _verus_source_entry(
        source_entries, kernel_source, description="verified kernel source"
    )
    kernel_path = root_dir / kernel_source
    if not kernel_path.is_file() or kernel_path.is_symlink():
        raise ValueError(
            f"cross-tool verified kernel source is not a regular file: {kernel_path}"
        )
    kernel_sha256 = _sha256_file(kernel_path)
    if kernel_source_entry.get("sha256") != kernel_sha256:
        raise ValueError(
            f"cross-tool verified kernel source digest mismatch: {kernel_source}"
        )
    kernel_source_text = kernel_path.read_text(encoding="utf-8")
    if claim.verus_source == _EFFECTIVE_LOCK_VERUS_SOURCE:
        shared_macro_payloads = _effective_lock_trace_shared_macro_payload(
            kernel_source_text, path=kernel_path
        )
    else:
        shared_macro_payloads = _shared_macro_payload(
            kernel_source_text,
            path=kernel_path,
            expected=claim.verified_kernel_shared_macro_sha256,
            description=f"{claim.constant} refinement",
        )
    kernel_items = rust_items(kernel_source_text, kernel)
    if len(kernel_items) != 1:
        raise ValueError(
            f"cross-tool claim {claim.constant} requires exactly one shared pure "
            f"kernel {kernel_source}!{kernel}; found {len(kernel_items)}"
        )
    kernel_item = kernel_items[0]
    if kernel_item.brace_context != ():
        raise ValueError(
            f"cross-tool verified kernel {kernel} must be a top-level production item"
        )
    if kernel_item.attributes or kernel_item.ancestor_inner_attributes:
        raise ValueError(
            f"cross-tool verified kernel {kernel} may not be gated or rewritten by attributes"
        )
    kernel_visibility = "pub" if claim.verified_kernel_public else "pub(crate)"
    kernel_const = "const " if claim.verified_kernel_const else ""
    expected_kernel_header = rust_code_tokens(
        f"{kernel_visibility} {kernel_const}fn {kernel}({kernel_parameters}) -> bool"
    )
    observed_kernel_header = _rust_item_header_tokens(kernel_item)
    if observed_kernel_header != expected_kernel_header:
        raise ValueError(
            f"cross-tool verified kernel {kernel} must have exact normalized pure "
            f"signature {(' '.join(expected_kernel_header))!r}; found "
            f"{(' '.join(observed_kernel_header))!r}"
        )
    kernel_body_tokens = rust_code_tokens(kernel_item.body)
    expected_kernel_body_tokens = rust_code_tokens(kernel_body)
    parameter_names = _rust_parameter_names(kernel_parameters)
    missing_inputs = [
        name for name in parameter_names if name not in kernel_body_tokens
    ]
    if (
        kernel_body_tokens in ((), ("true",), ("false",))
        or missing_inputs
        or _token_sequence_count(kernel_body_tokens, ("return", "true"))
        or _token_sequence_count(kernel_body_tokens, ("return", "false"))
    ):
        raise ValueError(
            f"cross-tool verified kernel {kernel} has a constant result or does "
            f"not depend on every reviewed projection input; missing {missing_inputs!r}"
        )
    if kernel_body_tokens != expected_kernel_body_tokens:
        raise ValueError(
            f"cross-tool verified kernel {kernel} must have exact normalized "
            f"reviewed body {(' '.join(expected_kernel_body_tokens))!r}; found "
            f"{(' '.join(kernel_body_tokens))!r}"
        )

    # The theorem must target a Verus specification with the same exact name,
    # signature, and reviewed body as the production kernel.  Checking only the
    # production item and theorem postcondition would permit a disconnected
    # same-named Verus predicate to return a constant while the executable
    # kernel remained intact.
    verus_kernel_items = rust_items(verus_source, kernel)
    if len(verus_kernel_items) != 1:
        raise ValueError(
            f"cross-tool claim {claim.constant} requires exactly one Verus "
            f"mirror kernel {claim.verus_source}!{kernel}; found "
            f"{len(verus_kernel_items)}"
        )
    verus_kernel_item = verus_kernel_items[0]
    if verus_kernel_item.brace_context != (("verus", "!"),):
        raise ValueError(
            f"cross-tool Verus mirror kernel {kernel} must be a top-level item "
            "in the verified verus! module"
        )
    if verus_kernel_item.attributes or verus_kernel_item.ancestor_inner_attributes:
        raise ValueError(
            f"cross-tool Verus mirror kernel {kernel} may not be gated or "
            "rewritten by attributes"
        )
    expected_verus_kernel_header = rust_code_tokens(
        f"pub closed spec fn {kernel}({kernel_parameters}) -> bool"
    )
    observed_verus_kernel_header = _rust_item_header_tokens(verus_kernel_item)
    if observed_verus_kernel_header != expected_verus_kernel_header:
        raise ValueError(
            f"cross-tool Verus mirror kernel {kernel} must have exact normalized "
            f"signature {(' '.join(expected_verus_kernel_header))!r}; found "
            f"{(' '.join(observed_verus_kernel_header))!r}"
        )
    verus_kernel_body_tokens = rust_code_tokens(verus_kernel_item.body)
    if verus_kernel_body_tokens != expected_kernel_body_tokens:
        raise ValueError(
            f"cross-tool Verus mirror kernel {kernel} must have the same exact "
            "reviewed body as production"
        )

    call_site_payloads: list[dict[str, Any]] = []
    for call_site in claim.production_call_sites:
        call_source_entry = _verus_source_entry(
            source_entries,
            call_site.source,
            description="authoritative production call-site source",
        )
        call_path = root_dir / call_site.source
        if not call_path.is_file() or call_path.is_symlink():
            raise ValueError(
                f"cross-tool production call-site source is not a regular file: {call_path}"
            )
        call_sha256 = _sha256_file(call_path)
        if call_source_entry.get("sha256") != call_sha256:
            raise ValueError(
                f"cross-tool production call-site source digest mismatch: "
                f"{call_site.source}"
            )
        call_source = call_path.read_text(encoding="utf-8")
        call_items = rust_items(call_source, call_site.item)
        if len(call_items) != 1:
            raise ValueError(
                f"cross-tool claim {claim.constant} requires exactly one "
                f"authoritative production item {call_site.source}!{call_site.item}; "
                f"found {len(call_items)}"
            )
        call_item = call_items[0]
        if call_item.brace_context != call_site.brace_context:
            raise ValueError(
                f"cross-tool production call site {call_site.source}!{call_site.item} "
                f"must have brace context {call_site.brace_context!r}; found "
                f"{call_item.brace_context!r}"
            )
        allowed_call_attributes = {("#", "[", "must_use", "]")}
        if (
            call_site.source == "crates/iroha_core/src/sumeragi/v2_runner.rs"
            and call_site.item == "run_inner"
        ):
            allowed_call_attributes.add(
                (
                    "#",
                    "[",
                    "allow",
                    "(",
                    "clippy",
                    "::",
                    "too_many_lines",
                    ")",
                    "]",
                )
            )
        unexpected_call_attributes = tuple(
            attribute
            for attribute in call_item.attributes
            if rust_code_tokens(attribute) not in allowed_call_attributes
        )
        if unexpected_call_attributes or call_item.ancestor_inner_attributes:
            raise ValueError(
                f"cross-tool production call site {call_site.source}!{call_site.item} "
                "may use only the non-gating approved attributes; found "
                f"{unexpected_call_attributes!r}"
            )
        required_expression = rust_code_tokens(call_site.required_expression)
        observed_expression_count = _token_sequence_count(
            rust_code_tokens(call_item.body), required_expression
        )
        if observed_expression_count != 1:
            raise ValueError(
                f"cross-tool production call site {call_site.source}!{call_site.item} "
                "must contain its exact kernel enforcement and projection once; "
                f"found {observed_expression_count}"
            )
        call_site_payloads.append(
            {
                "source": call_site.source,
                "source_sha256": call_sha256,
                "item": call_site.item,
                "item_token_sha256": _rust_item_token_sha256(call_item),
                "brace_context": [list(header) for header in call_site.brace_context],
                "projection": _normalized_rust_contract(call_site.projection),
                "required_expression": _normalized_rust_contract(
                    call_site.required_expression
                ),
            }
        )

    enter_view_identity_items: list[dict[str, str]] = []
    if claim.constant == "ProductionEnterViewUsesPostInstallEffectiveLock":
        if _ENTER_VIEW_IDENTITY_PRODUCTION_SOURCE not in claim.production_sources:
            raise ValueError(
                "cross-tool EnterView identity refinement must inventory its "
                "authoritative reducer source"
            )
        identity_path = root_dir / _ENTER_VIEW_IDENTITY_PRODUCTION_SOURCE
        if not identity_path.is_file() or identity_path.is_symlink():
            raise ValueError(
                "cross-tool EnterView identity source is not a regular file: "
                f"{identity_path}"
            )
        enter_view_identity_items = _enter_view_identity_production_item_payload(
            identity_path.read_text(encoding="utf-8"), path=identity_path
        )

    source_item_seals = _cross_tool_source_item_seal_payload(
        claim, root_dir=root_dir
    )

    production_sources: list[dict[str, str]] = []
    for relative in claim.production_sources:
        path = root_dir / relative
        if not path.is_file() or path.is_symlink():
            raise ValueError(
                f"cross-tool production source is not a regular file: {path}"
            )
        production_sources.append(
            {"path": relative, "sha256": _sha256_file(path)}
        )
    return {
        "constant": claim.constant,
        "contract_sha256": _canonical_json_sha256(
            _cross_tool_claim_contract_document(claim)
        ),
        "verus_theorem": claim.verus_theorem,
        "verus_source": claim.verus_source,
        "verus_source_sha256": verus_sha256,
        "verus_item_token_sha256": _rust_item_token_sha256(theorem_item),
        "verus_signature": " ".join(expected_theorem_header),
        "verus_parameters": _normalized_rust_contract(parameters),
        "verus_requires": _normalized_rust_contract(requires),
        "verus_ensures": _normalized_rust_contract(ensures),
        "verus_projection_builder": {
            "name": projection_builder,
            "signature": " ".join(expected_projection_builder_header),
            "item_token_sha256": observed_projection_builder_sha256,
        },
        "verified_kernel": {
            "name": kernel,
            "source": kernel_source,
            "source_sha256": kernel_sha256,
            "item_token_sha256": _rust_item_token_sha256(kernel_item),
            "verus_mirror_item_token_sha256": _rust_item_token_sha256(
                verus_kernel_item
            ),
            "signature": " ".join(expected_kernel_header),
            "verus_mirror_signature": " ".join(expected_verus_kernel_header),
            "theorem_projection": _normalized_rust_contract(
                theorem_projection
            ),
            "shared_macros": shared_macro_payloads,
        },
        "production_call_sites": call_site_payloads,
        "enter_view_identity_production_items": enter_view_identity_items,
        "source_item_seals": source_item_seals,
        "production_sources": production_sources,
    }


def build_cross_tool_evidence(
    ledger: dict[str, Any],
    *,
    tlaps_evidence: dict[str, Any],
    verus_evidence: dict[str, Any],
    formal_dir: Path = FORMAL_DIR,
    root_dir: Path = ROOT_DIR,
    expected_verus_source_manifest_sha256: str | None = None,
    verus_log_path: Path | None = None,
) -> dict[str, Any]:
    """Build the canonical evidence for every cross-tool-proved obligation."""

    contracts = _cross_tool_status_contracts(ledger)
    obligations = ledger.get("obligations")
    raw_cross_ids = (
        []
        if not isinstance(obligations, list)
        else [
            obligation.get("id")
            for obligation in obligations
            if isinstance(obligation, dict)
            and obligation.get("status") == "cross_tool_proved"
        ]
    )
    expected_cross_ids = [contract.obligation_id for contract in contracts]
    if raw_cross_ids != expected_cross_ids:
        raise ValueError(
            "cross_tool_proved obligations must be exactly the reviewed canonical "
            f"selection {expected_cross_ids!r}; found {raw_cross_ids!r}"
        )
    if not contracts:
        raise ValueError("ledger has no cross_tool_proved obligations")
    contract_errors = _cross_tool_contract_errors()
    if contract_errors:
        raise ValueError("; ".join(contract_errors))
    promotion_contract_errors = _cross_tool_promotion_contract_errors(contracts)
    if promotion_contract_errors:
        raise ValueError("; ".join(promotion_contract_errors))

    try:
        verus_module = _verus_evidence_contract_module()
        verus_errors = verus_module.validate_evidence(
            verus_evidence,
            root=root_dir,
            source_manifest_sha256=expected_verus_source_manifest_sha256,
            log_path=verus_log_path,
        )
    except (OSError, RuntimeError, UnicodeDecodeError, ValueError) as error:
        raise ValueError(f"cannot validate linked Verus evidence: {error}") from error
    if verus_errors:
        raise ValueError(
            "linked Verus evidence is invalid: " + "; ".join(verus_errors)
        )

    obligations: list[dict[str, Any]] = []
    for contract in contracts:
        obligations.append(
            {
                "id": contract.obligation_id,
                "ledger_symbol": contract.ledger_symbol,
                "dependencies": _cross_tool_dependency_entries(ledger, contract),
                "tla": _cross_tool_tla_payload(
                    contract,
                    tlaps_evidence=tlaps_evidence,
                    formal_dir=formal_dir,
                    root_dir=root_dir,
                ),
                "claims": [
                    _cross_tool_claim_payload(
                        claim,
                        verus_evidence=verus_evidence,
                        root_dir=root_dir,
                    )
                    for claim in contract.claims
                ],
            }
        )

    canonical_ledger_path = formal_dir / "proof_coverage.json"
    if not canonical_ledger_path.is_file() or canonical_ledger_path.is_symlink():
        raise ValueError(
            "cross-tool evidence requires a regular source-bound canonical "
            f"proof ledger: {canonical_ledger_path}"
        )
    canonical_ledger = load_ledger(canonical_ledger_path)
    if not isinstance(canonical_ledger, dict):
        raise ValueError("source-bound canonical proof ledger must be a JSON object")
    if canonical_ledger != ledger:
        raise ValueError(
            "cross-tool ledger differs from the source-bound canonical proof ledger"
        )

    formal_manifest = tlaps_evidence["source_manifest"]["sha256"]
    workspace_manifest = verus_evidence["source_manifest_sha256"]
    return {
        "schema_version": CROSS_TOOL_EVIDENCE_SCHEMA_VERSION,
        "protocol": "sumeragi-v2",
        "backend_verification": True,
        "ledger_sha256": _canonical_json_sha256(ledger),
        "component_evidence": {
            "tlaps_sha256": _canonical_json_sha256(tlaps_evidence),
            "verus_sha256": _canonical_json_sha256(verus_evidence),
        },
        "tools": {
            "tlaps": tlaps_evidence["tool"],
            "verus": verus_evidence["tool"],
        },
        "source_manifests": {
            "formal_sha256": formal_manifest,
            "workspace_sha256": workspace_manifest,
        },
        "obligations": obligations,
    }


def _first_json_mismatch(expected: Any, observed: Any, path: str = "$") -> str | None:
    """Return the first path at which two evidence values differ."""

    if type(expected) is not type(observed):
        return path
    if isinstance(expected, dict):
        if set(expected) != set(observed):
            return path
        for key in sorted(expected):
            mismatch = _first_json_mismatch(
                expected[key], observed[key], f"{path}.{key}"
            )
            if mismatch is not None:
                return mismatch
        return None
    if isinstance(expected, list):
        if len(expected) != len(observed):
            return path
        for index, (expected_item, observed_item) in enumerate(
            zip(expected, observed, strict=True)
        ):
            mismatch = _first_json_mismatch(
                expected_item, observed_item, f"{path}[{index}]"
            )
            if mismatch is not None:
                return mismatch
        return None
    return None if expected == observed else path


def _cross_tool_evidence_errors(
    ledger: dict[str, Any],
    cross_tool_evidence: dict[str, Any] | None,
    *,
    tlaps_evidence: dict[str, Any] | None,
    verus_evidence: dict[str, Any] | None,
    formal_dir: Path = FORMAL_DIR,
    root_dir: Path = ROOT_DIR,
    expected_verus_source_manifest_sha256: str | None = None,
    verus_log_path: Path | None = None,
) -> list[str]:
    """Reject any non-canonical, stale, or substituted cross-tool discharge."""

    contracts = _cross_tool_status_contracts(ledger)
    if not contracts:
        if cross_tool_evidence is not None:
            return [
                "cross-tool evidence is forbidden when no obligation is "
                "cross_tool_proved"
            ]
        return []
    if cross_tool_evidence is None:
        return ["release gate requires cross-tool refinement evidence"]
    if not isinstance(cross_tool_evidence, dict):
        return ["cross-tool refinement evidence must be a JSON object"]
    if not isinstance(tlaps_evidence, dict):
        return ["cross-tool refinement requires linked TLAPS evidence"]
    if not isinstance(verus_evidence, dict):
        return ["cross-tool refinement requires linked Verus evidence"]
    try:
        expected = build_cross_tool_evidence(
            ledger,
            tlaps_evidence=tlaps_evidence,
            verus_evidence=verus_evidence,
            formal_dir=formal_dir,
            root_dir=root_dir,
            expected_verus_source_manifest_sha256=(
                expected_verus_source_manifest_sha256
            ),
            verus_log_path=verus_log_path,
        )
    except (OSError, UnicodeDecodeError, ValueError) as error:
        return [f"cross-tool refinement evidence cannot be validated: {error}"]
    mismatch = _first_json_mismatch(expected, cross_tool_evidence)
    if mismatch is not None:
        return [
            "cross-tool refinement evidence does not match the canonical current "
            f"contract at {mismatch}"
        ]
    return []


def build_release_evidence(
    *,
    tlapm_version: str,
    log_dir: Path,
    formal_dir: Path = FORMAL_DIR,
    root_dir: Path = ROOT_DIR,
) -> dict[str, Any]:
    """Build source- and log-bound evidence after a successful strict TLAPM run."""

    version = " ".join(tlapm_version.split())
    if version != TLAPM_COMMIT[:7]:
        raise ValueError(
            f"TLAPM version must equal pinned identity {TLAPM_COMMIT[:7]}, found {version!r}"
        )
    source_manifest = _formal_source_manifest(formal_dir, root_dir)
    source_manifest_sha256 = source_manifest["sha256"]
    modules: list[dict[str, Any]] = []
    for module in RELEASE_PROOF_MODULES:
        log_path = log_dir / f"{module}.log"
        if not log_path.is_file() or log_path.is_symlink():
            raise ValueError(f"missing regular TLAPM proof log: {log_path}")
        source = log_path.read_text(encoding="utf-8")
        count = _tlapm_obligation_count(
            source,
            module=module,
            source_manifest_sha256=source_manifest_sha256,
        )
        if count is None or count <= 0:
            raise ValueError(
                "TLAPM proof log lacks the exact manifest-bound successful "
                f"suffix: {log_path}"
            )
        modules.append(
            {
                "module": module,
                "obligations_proved": count,
                "log": _relative_to_root(log_path, root_dir),
                "log_sha256": _sha256_file(log_path),
                "source_manifest_sha256": source_manifest_sha256,
            }
        )
    return {
        "schema_version": EVIDENCE_SCHEMA_VERSION,
        "protocol": "sumeragi-v2",
        "backend_verification": True,
        "tool": {
            "name": "TLAPM",
            "commit": TLAPM_COMMIT,
            "version": version,
        },
        "source_manifest": source_manifest,
        "modules": modules,
    }


def _module_sources(formal_dir: Path) -> tuple[dict[str, str], list[str]]:
    sources: dict[str, str] = {}
    errors: list[str] = []
    for module in REQUIRED_MODEL_MODULES:
        path = formal_dir / f"{module}.tla"
        if not path.is_file():
            errors.append(f"missing required TLA+ module: {path}")
            continue
        source = path.read_text(encoding="utf-8")
        header = MODULE_HEADER_RE.search(source)
        if header is None or header.group(1) != module:
            errors.append(f"{path}: module header must declare {module}")
        if not source.rstrip().endswith("===="):
            errors.append(f"{path}: module must end with ====")
        errors.extend(tla_shortcut_errors(path, source))
        if module in RELEASE_PROOF_MODULES and not ANY_THEOREM_DECLARATION_RE.search(
            strip_tla_comments(source)
        ):
            errors.append(f"{path}: release proof module must declare a theorem")
        sources[module] = source
    return sources, errors


def _resume_vote_witness_errors(formal_dir: Path) -> list[str]:
    """Pin the bounded historical locked-Commit counterexample witness."""

    errors: list[str] = []
    module_path = formal_dir / "SumeragiV2ResumeVoteWitness.tla"
    cfg_path = formal_dir / "resume_locked_commit_witness.cfg"
    if not module_path.is_file() or not cfg_path.is_file():
        return errors

    module_source = module_path.read_text(encoding="utf-8")
    recovered = _top_level_operator_body(
        module_source,
        "RecoveredHistoricalLockedCommitSigning",
        preserve_string_contents=True,
    )
    if recovered is None:
        errors.append(
            f"{module_path}: missing historical locked-Commit recovery predicate"
        )
    else:
        body, line = recovered
        normalized = " ".join(body.split())
        required = (
            "request \\in signVotes",
            "request.vote.signer = request.node",
            "request.vote.context = context",
            'request.vote.phase = "Commit"',
            "request.vote \\in commitIntents",
            "NodeTimedOut(request.node, request.vote.view)",
            "request.vote.view < nodeView[request.node]",
            "LockedPrepareRound(request.node, request.vote.view, request.vote.subject)",
            "generation[request.node] = MaxGeneration",
        )
        missing = [token for token in required if token not in normalized]
        if missing:
            errors.append(
                f"{module_path}:{line}: recovery predicate does not require the "
                f"exact timed-out historical locked Commit after restart; missing {missing}"
            )

    negated = _top_level_operator_body(
        module_source, "NoRecoveredHistoricalLockedCommitSigning"
    )
    if negated is None:
        errors.append(f"{module_path}: missing deliberately negated witness predicate")
    else:
        body, line = negated
        if " ".join(body.split()) != "~RecoveredHistoricalLockedCommitSigning":
            errors.append(
                f"{module_path}:{line}: witness invariant must be exactly the "
                "negation of RecoveredHistoricalLockedCommitSigning"
            )

    cfg_source = cfg_path.read_text(encoding="utf-8")
    required_cfg_lines = (
        "CHECK_DEADLOCK FALSE",
        "INVARIANT TypeInvariant",
        "INVARIANT NoRecoveredHistoricalLockedCommitSigning",
        "  N = 1",
        "  Honest = {0}",
        "  Responsive = {0}",
        "  MaxHeight = 0",
        "  MaxView = 1",
        "  MaxGeneration = 2",
    )
    missing_cfg_lines = [
        line
        for line in required_cfg_lines
        if cfg_source.splitlines().count(line) != 1
    ]
    if missing_cfg_lines:
        errors.append(
            f"{cfg_path}: recovery witness configuration must pin one timed-out "
            "view advance and one restart; missing or duplicated "
            f"{missing_cfg_lines}"
        )
    return errors


def _retired_liveness_errors(formal_dir: Path) -> list[str]:
    """Reject the old favourable-network liveness shortcut by exact symbol."""

    errors: list[str] = []
    for path in sorted(formal_dir.glob("*.tla")):
        stripped = strip_tla_comments(path.read_text(encoding="utf-8"))
        for symbol in RETIRED_LIVENESS_SYMBOLS:
            for match in re.finditer(rf"\b{re.escape(symbol)}\b", stripped):
                line = stripped.count("\n", 0, match.start()) + 1
                errors.append(
                    f"{path}:{line}: retired favourable-network liveness "
                    f"symbol {symbol} is prohibited"
                )
    return errors


def _bounded_view_dependency_errors(formal_dir: Path) -> list[str]:
    """Keep ``MaxView`` confined to the finite TLC substitution scaffold."""

    errors: list[str] = []
    allowed_core_lines = {"MaxView,", "FiniteViews == 0..MaxView"}
    for path in sorted(formal_dir.glob("*.tla")):
        stripped = strip_tla_comments(path.read_text(encoding="utf-8"))
        for line_number, line in enumerate(stripped.splitlines(), start=1):
            if "MaxView" not in line:
                continue
            if path.name == "SumeragiV2Core.tla" and line.strip() in allowed_core_lines:
                continue
            errors.append(
                f"{path}:{line_number}: MaxView is reserved for FiniteViews/TLC "
                "scaffolding; deductive protocol relations must use ViewDomain"
            )
    return errors


def _top_level_operator_body(
    source: str, symbol: str, *, preserve_string_contents: bool = False
) -> tuple[str, int] | None:
    """Return one top-level operator body and its first source line."""

    stripped = strip_tla_comments(
        source, preserve_string_contents=preserve_string_contents
    )
    declaration = re.compile(
        rf"(?m)^{re.escape(symbol)}\s*(?:\([^)=]*\))?\s*=="
    ).search(stripped)
    if declaration is None:
        return None
    body_start = declaration.end()
    next_declaration = re.compile(
        r"(?m)^(?:[A-Za-z_][A-Za-z0-9_]*\s*(?:\([^)=]*\))?\s*==|"
        r"[ \t]*(?:LOCAL[ \t]+)?"
        r"(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)\b|={4,}\s*$)"
    ).search(stripped, body_start)
    body_end = next_declaration.start() if next_declaration is not None else len(stripped)
    return stripped[body_start:body_end], stripped.count("\n", 0, body_start) + 1


def _top_level_theorem_body(
    source: str, symbol: str, *, preserve_string_contents: bool = False
) -> tuple[str, int] | None:
    """Return one top-level theorem body and its first source line."""

    stripped = strip_tla_comments(
        source, preserve_string_contents=preserve_string_contents
    )
    declaration = re.compile(
        rf"(?m)^[ \t]*(?:LOCAL[ \t]+)?"
        rf"(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)[ \t]+"
        rf"{re.escape(symbol)}\s*(?:\([^)=]*\))?\s*=="
    ).search(stripped)
    if declaration is None:
        return None
    body_start = declaration.end()
    next_declaration = re.compile(
        r"(?m)^(?:[A-Za-z_][A-Za-z0-9_]*\s*(?:\([^)=]*\))?\s*==|"
        r"[ \t]*(?:LOCAL[ \t]+)?"
        r"(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)\b|={4,}\s*$)"
    ).search(stripped, body_start)
    body_end = next_declaration.start() if next_declaration is not None else len(stripped)
    return stripped[body_start:body_end], stripped.count("\n", 0, body_start) + 1


def _proofless_release_theorem_errors(
    obligations: list[Any], module_sources: dict[str, str]
) -> list[str]:
    """Require every proofless release theorem to be exact, explicit debt."""

    errors: list[str] = []
    declaration = re.compile(
        r"(?m)^[ \t]*(?:LOCAL[ \t]+)?"
        r"(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)[ \t]+"
        r"([A-Za-z_][A-Za-z0-9_]*)\s*(?:\([^)=\n]*\))?\s*=="
    )
    proof = re.compile(r"(?m)^[ \t]*(?:BY|PROOF|OBVIOUS)\b")
    for module, source in module_sources.items():
        if module not in RELEASE_PROOF_MODULES:
            continue
        stripped = strip_tla_comments(source)
        for match in declaration.finditer(stripped):
            symbol = match.group(1)
            extracted = _top_level_theorem_body(source, symbol)
            if extracted is None or proof.search(extracted[0]) is not None:
                continue
            exact_entries = [
                obligation
                for obligation in obligations
                if isinstance(obligation, dict)
                and obligation.get("module") == module
                and obligation.get("symbol") == symbol
            ]
            if len(exact_entries) != 1:
                errors.append(
                    f"{module}.tla:{extracted[1]}: proofless release theorem "
                    f"{module}!{symbol} must have exactly one ledger entry using "
                    "its exact module and symbol"
                )
                continue
            status = exact_entries[0].get("status")
            obligation_id = exact_entries[0].get("id")
            cross_tool_contract = CROSS_TOOL_REFINEMENT_BY_ID.get(obligation_id)
            cross_tool_discharge = (
                status == "cross_tool_proved"
                and cross_tool_contract is not None
                and cross_tool_contract.module == module
                and cross_tool_contract.ledger_symbol == symbol
            )
            if status != "specified_unproved" and not cross_tool_discharge:
                errors.append(
                    f"{module}.tla:{extracted[1]}: proofless release theorem "
                    f"{module}!{symbol} must be ledgered specified_unproved, "
                    f"found {status!r}"
                )
    return errors


def _proof_obligation_inventory_errors(obligations: list[Any]) -> list[str]:
    """Require the ledger to match the independently reviewed release inventory."""

    errors: list[str] = []
    observed_ids: list[str] = []
    by_id: dict[str, dict[str, Any]] = {}
    for obligation in obligations:
        if not isinstance(obligation, dict):
            continue
        obligation_id = obligation.get("id")
        if not _nonempty_string(obligation_id):
            continue
        observed_ids.append(obligation_id)
        by_id.setdefault(obligation_id, obligation)

    expected_ids = list(REQUIRED_PROOF_OBLIGATION_INVENTORY)
    expected_id_set = set(expected_ids)
    for obligation_id, (expected_module, expected_symbol) in (
        REQUIRED_PROOF_OBLIGATION_INVENTORY.items()
    ):
        obligation = by_id.get(obligation_id)
        if obligation is None:
            errors.append(f"proof ledger is missing reviewed obligation {obligation_id}")
            continue
        if obligation.get("module") != expected_module:
            errors.append(
                f"proof obligation {obligation_id} must use reviewed module "
                f"{expected_module}"
            )
        if obligation.get("symbol") != expected_symbol:
            errors.append(
                f"proof obligation {obligation_id} must use reviewed symbol "
                f"{expected_symbol}"
            )

    for obligation_id in dict.fromkeys(observed_ids):
        if obligation_id not in expected_id_set:
            errors.append(f"proof ledger contains unreviewed obligation {obligation_id}")

    if observed_ids != expected_ids:
        errors.append(
            "proof ledger obligations must follow the reviewed canonical order; "
            f"expected {expected_ids}, found {observed_ids}"
        )
    return errors


def _proof_obligation_architecture_errors(
    obligations: list[Any], module_sources: dict[str, str]
) -> list[str]:
    """Bind release obligations to the non-circular production proof layers."""

    errors: list[str] = []
    by_id = {
        obligation.get("id"): obligation
        for obligation in obligations
        if isinstance(obligation, dict) and _nonempty_string(obligation.get("id"))
    }

    for obligation_id, (module, symbol) in FIXED_PROOF_OBLIGATION_TARGETS.items():
        obligation = by_id.get(obligation_id)
        if obligation is None:
            errors.append(f"proof ledger is missing required obligation {obligation_id}")
            continue
        where = f"proof obligation {obligation_id}"
        if obligation.get("module") != module:
            errors.append(f"{where} must use {module}")
        if obligation.get("symbol") != symbol:
            errors.append(f"{where} must use the direct theorem {symbol}")

    def check_direct_theorem(
        obligation_id: str,
        symbol: str,
        *,
        module: str,
        required_spec: str,
        forbidden: tuple[str, ...],
        exact_statement: str | None = None,
    ) -> None:
        obligation = by_id.get(obligation_id)
        if obligation is None:
            errors.append(f"proof ledger is missing required obligation {obligation_id}")
            return
        where = f"proof obligation {obligation_id}"
        if obligation.get("module") != module:
            errors.append(f"{where} must use {module}")
        if obligation.get("symbol") != symbol:
            errors.append(f"{where} must use the direct theorem {symbol}")
        source = module_sources.get(module)
        if source is None:
            return
        declaration = re.compile(
            rf"(?m)^[ \t]*(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)[ \t]+"
            rf"{re.escape(symbol)}\s*=="
        )
        if declaration.search(strip_tla_comments(source)) is None:
            errors.append(
                f"{where} must be one closed theorem universally quantifying initialContext"
            )
        extracted = _top_level_theorem_body(source, symbol)
        if extracted is None:
            return
        body, line = extracted
        statement = re.split(
            r"(?m)^[ \t]*(?:BY|PROOF|OBVIOUS)\b", body, maxsplit=1
        )[0]
        normalized_statement = " ".join(statement.split())
        if exact_statement is not None and normalized_statement != exact_statement:
            errors.append(
                f"{module}.tla:{line}: {symbol} must state only "
                f"{exact_statement!r}; found {normalized_statement!r}"
            )
        if re.search(
            rf"\b{re.escape(required_spec)}\s*\(\s*initialContext\s*\)", body
        ) is None:
            errors.append(
                f"{module}.tla:{line}: {symbol} must directly require "
                f"{required_spec}(initialContext)"
            )
        for retired in forbidden:
            if re.search(rf"\b{re.escape(retired)}\b", body):
                errors.append(
                    f"{module}.tla:{line}: {symbol} may not depend on "
                    f"legacy global-barrier operator {retired}"
                )

    def check_closed_theorem(
        obligation_id: str,
        symbol: str,
        *,
        module: str,
        exact_statement: str,
        forbidden: tuple[str, ...],
    ) -> None:
        obligation = by_id.get(obligation_id)
        if obligation is None:
            errors.append(f"proof ledger is missing required obligation {obligation_id}")
            return
        where = f"proof obligation {obligation_id}"
        if obligation.get("module") != module:
            errors.append(f"{where} must use {module}")
        if obligation.get("symbol") != symbol:
            errors.append(f"{where} must use the direct theorem {symbol}")
        source = module_sources.get(module)
        if source is None:
            return
        declaration = re.compile(
            rf"(?m)^[ \t]*(?:THEOREM|LEMMA|COROLLARY|PROPOSITION)[ \t]+"
            rf"{re.escape(symbol)}\s*=="
        )
        if declaration.search(strip_tla_comments(source)) is None:
            errors.append(f"{where} must be one closed, unparameterized theorem")
        extracted = _top_level_theorem_body(source, symbol)
        if extracted is None:
            return
        body, line = extracted
        statement = re.split(
            r"(?m)^[ \t]*(?:BY|PROOF|OBVIOUS)\b", body, maxsplit=1
        )[0]
        normalized_statement = " ".join(statement.split())
        if normalized_statement != exact_statement:
            errors.append(
                f"{module}.tla:{line}: {symbol} must state only "
                f"{exact_statement!r}; found {normalized_statement!r}"
            )
        for retired in forbidden:
            if re.search(rf"\b{re.escape(retired)}\b", body):
                errors.append(
                    f"{module}.tla:{line}: {symbol} may not depend on "
                    f"legacy global-barrier operator {retired}"
                )

    for obligation_id, symbol in ARBITRARY_CONTEXT_SAFETY_OBLIGATIONS.items():
        property_wrapper = ARBITRARY_CONTEXT_SAFETY_PROPERTY_WRAPPERS[obligation_id]
        check_direct_theorem(
            obligation_id,
            symbol,
            module="SumeragiV2Proofs",
            required_spec="CoreSpecAt",
            forbidden=("Spec", "NextV2", "AdvanceContext"),
            exact_statement=(
                f"\\A initialContext: "
                f"{property_wrapper}(CoreSpecAt(initialContext))"
            ),
        )
    for obligation_id, symbol in ASYNC_LIVENESS_OBLIGATIONS.items():
        property_wrapper = ASYNC_LIVENESS_PROPERTY_WRAPPERS[obligation_id]
        exact_statement = ASYNC_LIVENESS_EXACT_STATEMENTS.get(
            obligation_id,
            f"\\A initialContext: "
            f"{property_wrapper}(AsyncSpecAt(initialContext))",
        )
        check_direct_theorem(
            obligation_id,
            symbol,
            module="SumeragiV2AsyncLivenessProofs",
            required_spec="AsyncSpecAt",
            forbidden=("Spec", "NextV2", "AdvanceContext"),
            exact_statement=exact_statement,
        )
    for obligation_id, (symbol, property_wrapper) in CHAIN_SAFETY_OBLIGATIONS.items():
        check_closed_theorem(
            obligation_id,
            symbol,
            module="SumeragiV2ChainEpochProofs",
            exact_statement=f"{property_wrapper}(ChainEpochSpec)",
            forbidden=(
                "AsyncSpec",
                "Spec",
                "NextV2",
                "AdvanceContext",
                "CommonAppliedSubject",
            ),
        )
    return errors


def _proof_status_dependency_errors(obligations: list[Any]) -> list[str]:
    """Require compositional theorems to follow and wait for prerequisites."""

    errors: list[str] = []
    by_id: dict[str, dict[str, Any]] = {}
    positions: dict[str, int] = {}
    for index, obligation in enumerate(obligations):
        if not isinstance(obligation, dict):
            continue
        obligation_id = obligation.get("id")
        if not _nonempty_string(obligation_id) or obligation_id in by_id:
            continue
        by_id[obligation_id] = obligation
        positions[obligation_id] = index

    for dependent_id, prerequisite_ids in PROOF_STATUS_DEPENDENCIES.items():
        dependent = by_id.get(dependent_id)
        if dependent is None:
            continue
        for prerequisite_id in prerequisite_ids:
            prerequisite = by_id.get(prerequisite_id)
            if prerequisite is None:
                errors.append(
                    f"proof obligation {dependent_id} is missing prerequisite "
                    f"{prerequisite_id}"
                )
                continue
            if positions[prerequisite_id] >= positions[dependent_id]:
                errors.append(
                    f"proof obligation {dependent_id} must appear after prerequisite "
                    f"{prerequisite_id}"
                )
            if (
                dependent.get("status") in PROVED_STATUS_VALUES
                and prerequisite.get("status") not in PROVED_STATUS_VALUES
            ):
                if dependent.get("status") == "tlaps_proved":
                    errors.append(
                        f"proof obligation {dependent_id} cannot be tlaps_proved "
                        f"before prerequisite {prerequisite_id} is tlaps_proved"
                    )
                else:
                    errors.append(
                        f"proof obligation {dependent_id} cannot be "
                        "cross_tool_proved before prerequisite "
                        f"{prerequisite_id} is proved"
                    )
    return errors


def _reachable_oracle_guard_errors(formal_dir: Path) -> list[str]:
    """Reject proof-history oracles from executable Core action bodies."""

    path = formal_dir / "SumeragiV2Core.tla"
    if not path.is_file():
        return []
    source = path.read_text(encoding="utf-8")
    errors: list[str] = []
    for action, forbidden in REACHABLE_ACTION_ORACLES.items():
        extracted = _top_level_operator_body(source, action)
        if extracted is None:
            errors.append(f"{path}: missing oracle-audited Core action {action}")
            continue
        body, first_line = extracted
        for oracle in forbidden:
            for match in re.finditer(rf"\b{re.escape(oracle)}\b", body):
                line = first_line + body.count("\n", 0, match.start())
                errors.append(
                    f"{path}:{line}: executable action {action} may not use "
                    f"proof-history oracle {oracle}"
                )
    return errors


def _async_spec_shape_errors(formal_dir: Path) -> list[str]:
    """Keep deductive and finite specs on one canonical state/fairness surface."""

    path = formal_dir / "SumeragiV2AsyncNetwork.tla"
    expected = {
        "AsyncBaseInit": "AsyncBaseInitAt(ContextRecord(0, <<>>))",
        "AsyncInitAt": "AsyncBaseInitAt(initialContext) /\\ ViewDomain = Nat",
        "AsyncInit": "AsyncInitAt(ContextRecord(0, <<>>))",
        "AsyncFiniteInitAt": (
            "AsyncBaseInitAt(initialContext) /\\ ViewDomain = FiniteViews"
        ),
        "AsyncFiniteInit": "AsyncFiniteInitAt(ContextRecord(0, <<>>))",
        "AsyncAllVars": "<<vars, AsyncSchedulerVars, AsyncRecoveryVars>>",
        "AsyncSpec": "AsyncInit /\\ [][AsyncNext]_AsyncAllVars /\\ AsyncFairness",
        "AsyncSpecAt": (
            "AsyncInitAt(initialContext) /\\ [][AsyncNext]_AsyncAllVars "
            "/\\ AsyncFairnessAt(initialContext)"
        ),
        "AsyncFiniteSpec": (
            "AsyncFiniteInit /\\ [][AsyncNext]_AsyncAllVars /\\ AsyncFairness"
        ),
        "AsyncFiniteSpecAt": (
            "AsyncFiniteInitAt(initialContext) "
            "/\\ [][AsyncNext]_AsyncAllVars "
            "/\\ AsyncFairnessAt(initialContext)"
        ),
        "AsyncFairness": "AsyncFairnessAt(ContextRecord(0, <<>>))",
    }
    errors: list[str] = []
    if path.is_file():
        source = path.read_text(encoding="utf-8")
        for symbol, exact_body in expected.items():
            extracted = _top_level_operator_body(source, symbol)
            if extracted is None:
                errors.append(f"{path}: missing required asynchronous operator {symbol}")
                continue
            body, line = extracted
            normalized = " ".join(body.split())
            if normalized != exact_body:
                errors.append(
                    f"{path}:{line}: {symbol} must equal only {exact_body!r}; "
                    f"found {normalized!r}"
                )

        stripped = strip_tla_comments(source)
        for forbidden in (
            "AsyncTlcAllVars",
            "AsyncTlcFairnessAt",
            "AsyncTlcFairness",
        ):
            for match in re.finditer(rf"\b{re.escape(forbidden)}\b", stripped):
                line = stripped.count("\n", 0, match.start()) + 1
                errors.append(
                    f"{path}:{line}: TLC-only duplicate {forbidden} is prohibited; "
                    "finite and deductive specs must share AsyncAllVars and "
                    "AsyncFairnessAt"
                )

        public_fairness = _top_level_operator_body(
            source, "AsyncFairnessAt", preserve_string_contents=True
        )
        if public_fairness is None:
            errors.append(f"{path}: missing required asynchronous operator AsyncFairnessAt")
        else:
            public_body, public_line = public_fairness
            public_subscripts = set(
                re.findall(r"\bWF_([A-Za-z][A-Za-z0-9_]*)\s*\(", public_body)
            )
            if public_subscripts != {"AsyncAllVars"}:
                errors.append(
                    f"{path}:{public_line}: AsyncFairnessAt may use only the "
                    f"public AsyncAllVars subscript; found {sorted(public_subscripts)}"
                )

    for module in ("SumeragiV2LivenessProofs", "SumeragiV2AsyncLivenessProofs"):
        proof_path = formal_dir / f"{module}.tla"
        if not proof_path.is_file():
            continue
        stripped = strip_tla_comments(proof_path.read_text(encoding="utf-8"))
        for match in re.finditer(r"\bAsyncFiniteSpec\b", stripped):
            line = stripped.count("\n", 0, match.start()) + 1
            errors.append(
                f"{proof_path}:{line}: deductive liveness proofs must use "
                "unbounded AsyncSpec, not the finite TLC instance"
            )
    return errors


def _async_proof_architecture_errors(formal_dir: Path) -> list[str]:
    """Require checked scheduler closure and the exact Core-step refinement."""

    path = formal_dir / "SumeragiV2AsyncLivenessProofs.tla"
    if not path.is_file():
        return []
    source = path.read_text(encoding="utf-8")
    stripped = strip_tla_comments(source)
    has_strong_type_architecture = (
        _top_level_operator_body(source, "AsyncStrongTypeInvariant") is not None
    )
    has_transport_content_architecture = (
        _top_level_operator_body(source, "AsyncTransportContentTypeInvariant")
        is not None
        or _top_level_theorem_body(
            source, "ExecuteCommandPreservesTransportContentType"
        )
        is not None
    )
    expected = {
        "AsyncStepRefinementObligation": "AsyncNext => [Next]_vars",
        "AsyncTypeInvariantObligation": (
            "\\A initialContext: AsyncSpecAt(initialContext) => []AsyncTypeInvariant"
        ),
        "AsyncNextPreservesNormalProposalPrepareCandidate": (
            "\\A candidate: /\\ NormalProposalPrepareCandidate(candidate) "
            "/\\ AsyncNext => NormalProposalPrepareCandidate(candidate)'"
        ),
    }
    if has_strong_type_architecture:
        recovery_preservation_premises = (
            "/\\ StrongInductiveInvariant /\\ AsyncTypeInvariant "
            "/\\ AsyncRecoveryTypeInvariant /\\ AsyncRestartAuthorityInvariant "
            "/\\ AsyncRecoveryExecutionInvariant /\\ AsyncNext"
        )
        expected.update({
            "AsyncNextPreservesRecoveryInvariants": (
                f"{recovery_preservation_premises} "
                "=> /\\ AsyncRecoveryTypeInvariant' "
                "/\\ AsyncRestartAuthorityInvariant'"
            ),
            "AsyncNextPreservesRecoveryExecutionInvariant": (
                f"{recovery_preservation_premises} "
                "=> AsyncRecoveryExecutionInvariant'"
            ),
        })
    if has_transport_content_architecture:
        expected["ExecuteDecisionFetchPreservesTransportContentType"] = (
            "\\A command: (/\\ StrongInductiveInvariant "
            "/\\ AsyncTypeInvariant /\\ AsyncCandidateTyped(command) "
            "/\\ ExecuteDecisionFetch(command)) "
            "=> AsyncTransportContentTypeInvariant'"
        )
    if (
        (formal_dir / "proof_coverage.json").is_file()
        and (formal_dir / "SumeragiV2LivenessProofs.tla").is_file()
    ):
        expected.update({
            "AsyncSpecAlwaysProgressOwnershipInvariant": (
                "\\A initialContext: AsyncSpecAt(initialContext) "
                "=> []AsyncProgressOwnershipInvariant"
            ),
            "AsyncIngressCapacityGeometry": (
                "ModelConfiguration => "
                "/\\ Cardinality(ValidatorIds) = N "
                "/\\ Cardinality(AsyncIngressSources) = N + 1"
            ),
            "OneRemovalIncreasesSourceProtectionByAtMostOne": (
                "\\A source, before, selected: "
                "/\\ before \\in Seq(Range(before)) "
                "/\\ selected \\in 1..Len(before) => "
                "LET after == SequenceWithoutIndex(before, selected) "
                "IN IngressSourceProtectionPotential(source, after) <= "
                "IngressSourceProtectionPotential(source, before) + 1"
            ),
            "ProtectedProgressSlotUniverseSize": (
                "ModelConfiguration => "
                "/\\ IsFiniteSet(ProtectedProgressSlotUniverse) "
                "/\\ Cardinality(ProtectedProgressSlotUniverse) = 2 * N + 3"
            ),
            "ProtectedProgressSlotIdIsBounded": (
                "\\A command: /\\ N \\in Nat \\ {0} "
                "/\\ AsyncCandidateTyped(command) "
                "/\\ ProtectedProgressCommand(command) "
                "=> ProtectedProgressSlotId(command) \\in 0..(2 * N + 2)"
            ),
            "AppendFreshServeJobPreservesNonceOwnership": (
                "\\A queue, job: /\\ AsyncIoSequenceTyped(queue) "
                "/\\ AsyncIoServeNonceOwnership(queue) "
                "/\\ AsyncIoJobTyped(job) /\\ job.class = \" \" "
                "/\\ job.nonce \\notin {queue[index].nonce: "
                "index \\in AsyncIoServeIndices(queue)} "
                "=> AsyncIoServeNonceOwnership(Append(queue, job))"
            ),
            "AppendNonServeJobPreservesNonceOwnership": (
                "\\A queue, job: /\\ AsyncIoSequenceTyped(queue) "
                "/\\ AsyncIoServeNonceOwnership(queue) "
                "/\\ job.class # \" \" "
                "=> AsyncIoServeNonceOwnership(Append(queue, job))"
            ),
            "TailPreservesServeNonceOwnership": (
                "\\A queue: /\\ AsyncIoSequenceTyped(queue) "
                "/\\ AsyncIoServeNonceOwnership(queue) "
                "/\\ Len(queue) > 0 "
                "=> AsyncIoServeNonceOwnership(Tail(queue))"
            ),
        })
    errors: list[str] = []
    if has_strong_type_architecture:
        recovery_execution = _top_level_operator_body(
            source,
            "AsyncRecoveryExecutionInvariant",
            preserve_string_contents=True,
        )
        expected_recovery_execution = (
            'asyncRecoveryPhase = "Replaying" => '
            "/\\ asyncOutstandingTags[asyncRecoveryNode] = {} "
            "/\\ SequenceHasUniqueValues(asyncRecoveryReplayQueue) "
            "/\\ SequenceSet(asyncRecoveryReplayQueue) \\cap "
            "ResponsiveReplayScheduledCandidates(asyncRecoveryNode) = {}"
        )
        if recovery_execution is None:
            errors.append(f"{path}: missing AsyncRecoveryExecutionInvariant")
        else:
            body, line = recovery_execution
            normalized = " ".join(body.split())
            if normalized != expected_recovery_execution:
                errors.append(
                    f"{path}:{line}: AsyncRecoveryExecutionInvariant must equal "
                    f"only {expected_recovery_execution!r}; found {normalized!r}"
                )
        bad_recovery_prime_scope = re.compile(
            r"ResponsiveReplayScheduledCandidates\s*\(\s*"
            r"asyncRecoveryNode\s*'\s*\)"
        )
        for match in bad_recovery_prime_scope.finditer(stripped):
            line = stripped.count("\n", 0, match.start()) + 1
            errors.append(
                f"{path}:{line}: prime ResponsiveReplayScheduledCandidates as a "
                "whole state expression; priming asyncRecoveryNode inside the "
                "call leaves the scheduled-candidate inventory unprimed"
            )
        strong_type = _top_level_operator_body(
            source,
            "AsyncStrongTypeInvariant",
            preserve_string_contents=True,
        )
        expected_strong_type = (
            "/\\ StrongInductiveInvariant /\\ AsyncSchedulerTypeInvariant "
            "/\\ ReceivedTimeoutVotePoolInvariant "
            "/\\ AsyncRecoveryTypeInvariant /\\ AsyncRestartAuthorityInvariant "
            "/\\ AsyncRecoveryExecutionInvariant "
            "/\\ AsyncHistoricalLockRestartAuthorityTypeInvariant "
            "/\\ HistoricalLockRestartAuthoritySourceRetentionInvariant"
        )
        if strong_type is None:
            errors.append(f"{path}: missing AsyncStrongTypeInvariant")
        else:
            body, line = strong_type
            normalized = " ".join(body.split())
            if normalized != expected_strong_type:
                errors.append(
                    f"{path}:{line}: AsyncStrongTypeInvariant must include the "
                    "exact recovery execution premise; expected "
                    f"{expected_strong_type!r}; found {normalized!r}"
                )
    for symbol, exact_statement in expected.items():
        extracted = _top_level_theorem_body(source, symbol)
        if extracted is None:
            errors.append(f"{path}: missing release theorem {symbol}")
            continue
        body, line = extracted
        statement = re.split(
            r"(?m)^[ \t]*(?:BY|PROOF|OBVIOUS)\b", body, maxsplit=1
        )[0]
        normalized = " ".join(statement.split())
        if normalized != exact_statement:
            errors.append(
                f"{path}:{line}: {symbol} must state only "
                f"{exact_statement!r}; found {normalized!r}"
            )
    if has_transport_content_architecture:
        execute_command_preservation = _top_level_theorem_body(
            source, "ExecuteCommandPreservesTransportContentType"
        )
        if execute_command_preservation is None:
            errors.append(
                f"{path}: missing release theorem "
                "ExecuteCommandPreservesTransportContentType"
            )
        else:
            body, line = execute_command_preservation
            decision_fetch_case = re.search(
                r"(?ms)^[ \t]*<2>2\.\s*(.*?)(?=^[ \t]*<2>3\.)",
                body,
            )
            expected_decision_fetch_case = (
                "CASE ExecuteDecisionFetch(command) "
                "BY <1>1, <2>2, "
                "ExecuteDecisionFetchPreservesTransportContentType"
            )
            normalized_case = (
                None
                if decision_fetch_case is None
                else " ".join(decision_fetch_case.group(1).split())
            )
            if normalized_case != expected_decision_fetch_case:
                errors.append(
                    f"{path}:{line}: ExecuteCommandPreservesTransportContentType "
                    "must retain the exact dedicated ExecuteDecisionFetch case; "
                    f"found {normalized_case!r}"
                )
    if has_strong_type_architecture:
        strong_type_preservation = _top_level_theorem_body(
            source, "AsyncNextPreservesStrongTypeInvariant"
        )
        if strong_type_preservation is None:
            errors.append(
                f"{path}: missing release theorem "
                "AsyncNextPreservesStrongTypeInvariant"
            )
        else:
            body, line = strong_type_preservation
            expected_core_type_projections = (
                "<2>1. StrongInductiveInvariant "
                "BY <1>1 DEF AsyncStrongTypeInvariant "
                "<2>2. AsyncTypeInvariant "
                "BY <1>1, AsyncStrongTypeProjectsAsyncType"
            )
